import express from 'express';
const app = express();

// 报表导出服务：根据查询参数生成可在线预览的 HTML 报表
interface ExportQuery { title?: string; note?: string; }

// 内部数据源：报表行由服务端生成，外部不可控
function loadRows(): string[][] {
  return [['华东大区', '128900'], ['华南大区', '96400']];
}

app.get('/report/export', (req, res) => {
  const q = req.query as ExportQuery;
  // 入口1：报表标题，来自 URL 查询参数，攻击者可控
  const title = typeof q.title === 'string' ? q.title : '月度销售报表';
  // 入口2：报表备注，同样来自 URL 查询参数
  const note = typeof q.note === 'string' ? q.note : '';

  let rowsHtml = '';
  for (const [region, amount] of loadRows()) {
    rowsHtml += `<tr><td>${region}</td><td>${amount}</td></tr>`;
  }

  // 将用户输入直接拼入 HTML，未做任何实体转义
  const html = `<html><head><title>${title}</title></head><body>`
    + `<h1>${title}</h1><p>备注：${note}</p>`
    + `<table border="1">${rowsHtml}</table></body></html>`;

  // 以 inline 方式返回，浏览器将直接渲染该 HTML
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Content-Disposition', 'inline; filename="report.html"');
  res.status(200).send(html);
});

app.listen(8080);
```

