import amqp from 'amqplib';
import { exec } from 'child_process';

// 视频转码任务消费者：从 RabbitMQ 队列接收任务并调用 ffmpeg 处理
async function startTranscodeConsumer(): Promise<void> {
  const conn = await amqp.connect(process.env.AMQP_URL ?? 'amqp://localhost');
  const channel = await conn.createChannel();
  const queue = 'media.transcode.jobs';
  await channel.assertQueue(queue, { durable: true });

  channel.consume(queue, (msg) => {
    if (msg === null) return;
    // 消息体为 JSON，字段含 fileId 与 format
    const payload = JSON.parse(msg.content.toString());
    const fileId: string = payload.fileId;
    const format: string = payload.format;

    // 直接拼接命令行执行转码
    const cmd = `ffmpeg -i /data/uploads/${fileId} -f ${format} /data/output/${fileId}.out`;
    exec(cmd, { timeout: 60000 }, (err, stdout) => {
      if (err) {
        console.error('transcode failed:', err.message);
        channel.nack(msg, false, false);
        return;
      }
      console.log('transcode ok:', stdout.slice(0, 120));
      channel.ack(msg);
    });
  });
}

startTranscodeConsumer().catch((e) => console.error(e));
```

