import express from 'express';
import { render } from 'ejs';

const app = express();

// 模板渲染辅助：为运营后台提供邮件/页面模板的即时预览能力
// 模板字符串支持 EJS 的插值语法

interface RenderContext {
  username: string;
  points: number;
}

// 仅统一换行符便于前端展示，不做任何模板语法层面的处理
function normalizeNewlines(tpl: string): string {
  return tpl.replace(/\r\n/g, '\n');
}

// 核心渲染辅助：将传入的模板字符串直接交给模板引擎编译执行
function renderTemplate(tpl: string, ctx: RenderContext): string {
  const normalized = normalizeNewlines(tpl);
  return render(normalized, ctx);
}

// 预览接口：运营人员通过 tpl 查询参数传入自定义模板内容
app.get('/template/preview', (req, res) => {
  const tpl = typeof req.query.tpl === 'string' ? req.query.tpl : 'Hello <%= username %>';
  const ctx: RenderContext = {
    username: String(req.query.username ?? 'anonymous'),
    points: Number(req.query.points ?? 0)
  };
  res.type('html').send(renderTemplate(tpl, ctx));
});

app.listen(3000, () => console.log('preview service started on 3000'));
```

