import axios from 'axios';

// 数据导入适配器：根据用户提交的上游地址拉取外部数据并返回预览
interface ImportTask {
  sourceUrl: string;  // 用户在导入向导中填写的上游数据源地址
  format: string;
}

// 从 HTTP 请求体解析导入任务（外部输入入口）
function parseTask(body: Record<string, unknown>): ImportTask {
  return {
    sourceUrl: String(body.sourceUrl ?? ''),
    format: String(body.format ?? 'json'),
  };
}

// 服务端发起请求：直接访问传入的 URL
async function fetchSource(url: string): Promise<string> {
  const resp = await axios.get(url, { timeout: 5000, maxRedirects: 5 });
  return typeof resp.data === 'string' ? resp.data : JSON.stringify(resp.data);
}

// 导入适配器主入口
export async function runImportAdapter(req: { body: Record<string, unknown> }) {
  const task = parseTask(req.body);
  // 直接使用用户提供的 URL 发起服务端请求，未做任何地址校验
  const raw = await fetchSource(task.sourceUrl);
  return { ok: true, format: task.format, preview: raw.slice(0, 200) };
}
```

