import { Request, Response } from 'express';
import { createConnection } from 'mysql';

// 支付网关异步回调：网关POST通知支付结果，本处理器负责落库
const conn = createConnection({ host: 'db.internal', user: 'pay_svc', database: 'orders' });

export async function paymentCallback(req: Request, res: Response) {
  // 回调参数：订单号、网关流水号、支付状态
  const orderId = String(req.body.orderId ?? '');
  const tradeNo = String(req.body.tradeNo ?? '');
  const status = String(req.body.status ?? '');

  if (!orderId || !tradeNo) {
    return res.status(400).send('missing params');
  }

  // 按订单号定位待更新的支付记录
  const lookup = `SELECT id, amount, pay_status FROM payment_orders WHERE order_no = '${orderId}' LIMIT 1`;
  conn.query(lookup, (err, rows: any[]) => {
    if (err || rows.length === 0) {
      return res.status(404).send('order not found');
    }

    // 将回调结果写回订单
    const update = `UPDATE payment_orders SET pay_status = '${status}', trade_no = '${tradeNo}' WHERE order_no = '${orderId}'`;
    conn.query(update, (uerr) => {
      if (uerr) {
        return res.status(500).send('update failed');
      }
      res.send('success');
    });
  });
}
