// 邮件模板服务：支持导入序列化模板对象，模板可内嵌自定义渲染函数供运营灵活配置
import express from 'express';
import { unserialize } from 'node-serialize';
import * as fs from 'fs';

const app = express();
app.use(express.json());

interface MailTemplate {
  name: string;
  subject: string;
  render: (vars: Record<string, string>) => string;
}

// 入口1：POST /api/templates/import，请求体直接携带序列化模板字符串
app.post('/api/templates/import', (req, res) => {
  const raw: string = req.body.template; // 外部输入入口
  if (typeof raw !== 'string' || raw.length === 0) {
    return res.status(400).json({ error: 'template required' });
  }
  // 还原模板对象；node-serialize 会把序列化串中的函数体重新实例化为可调用函数
  const tpl = unserialize<MailTemplate>(raw); // sink：反序列化不可信数据
  const preview = tpl.render({ user: 'guest' }); // 立即调用还原出的渲染函数
  fs.writeFileSync(`/tmp/tpl-${tpl.name}.json`, JSON.stringify(preview));
  res.json({ ok: true, preview });
});

// 入口2：GET /api/templates/file/:name，读取运营上传的序列化模板文件（二阶通道）
app.get('/api/templates/file/:name', (req, res) => {
  const raw = fs.readFileSync(`/var/uploads/${req.params.name}`, 'utf8');
  const tpl = unserialize<MailTemplate>(raw); // 同一 sink 的第二入口
  res.send(tpl.render({ user: 'guest' }));
});

app.listen(3000, () => console.log('mail template service listening on 3000'));
