import express from 'express';

const app = express();

// 会话管理组件：校验客户端上送的会话令牌，格式合法才放行会话
// 令牌主体允许点/下划线分段（兼容旧版令牌），签名段为 32 位十六进制
const SESSION_TOKEN_RE = /^(sess-)?([a-zA-Z0-9]+[._]?)+-([a-f0-9]{32})$/;

// 从 Cookie 头提取会话令牌，取出的值为攻击者完全可控的外部输入
function extractSessionToken(cookieHeader: string): string | null {
  for (const part of cookieHeader.split(';')) {
    const idx = part.indexOf('=');
    if (idx > 0 && part.slice(0, idx).trim() === 'session_token') {
      return part.slice(idx + 1).trim();
    }
  }
  return null;
}

// 校验通过后才建立会话上下文
function verifySession(cookieHeader: string): boolean {
  const token = extractSessionToken(cookieHeader);
  if (token === null) return false;
  return SESSION_TOKEN_RE.test(token);
}

app.post('/session/verify', (req, res) => {
  const ok = verifySession(String(req.headers['cookie'] ?? ''));
  if (ok) {
    res.json({ authenticated: true });
  } else {
    res.status(401).json({ authenticated: false });
  }
});

app.listen(3000);
```

