import fs from 'fs';
import path from 'path';

// 订单处理后台任务：消费队列消息，将订单回执导出为文件
interface OrderJob {
  orderId: string;
  exportName: string; // 运营端提交的导出文件名
  content: string;
}

// 后台任务入口：接收消息队列投递的原始 JSON 消息
export function processOrderExport(rawMessage: string): void {
  const job: OrderJob = JSON.parse(rawMessage); // 外部输入入口

  const exportDir = '/var/order-exports';
  // 用消息中的文件名拼接导出目标路径
  const targetPath = path.join(exportDir, job.exportName);

  // 仅确保基础目录存在，未校验最终路径范围
  if (!fs.existsSync(exportDir)) {
    fs.mkdirSync(exportDir, { recursive: true });
  }

  // 将回执内容写入目标路径
  fs.writeFileSync(targetPath, job.content, 'utf8');
}
