import { createClient } from 'redis';
import { exec } from 'child_process';

// 消息队列消费者：处理上传文件的归档任务
const redis = createClient({ url: 'redis://127.0.0.1:6379' });

interface JobMessage {
  jobId: string;
  fileName: string; // 客户端提交的文件名，未做任何过滤
}

async function startConsumer() {
  await redis.connect();
  while (true) {
    // 入口：从 Redis 队列阻塞拉取任务，消息体由外部生产者写入
    const item = await redis.blPop('jobs:archive', 0);
    if (!item) continue;
    const job: JobMessage = JSON.parse(item.message);

    // 将用户可控的 fileName 直接拼进 shell 命令字符串
    const cmd = `tar -czf /tmp/archive/${job.jobId}.tgz ${job.fileName}`;

    // sink：exec 底层经 /bin/sh -c 执行拼接后的命令
    exec(cmd, (err, stdout) => {
      if (err) {
        console.error(`job ${job.jobId} failed: ${err.message}`);
        return;
      }
      console.log(`job ${job.jobId} done: ${stdout}`);
    });
  }
}

startConsumer();
```

