import express from 'express';
import fs from 'fs';
import path from 'path';

const app = express();
app.use(express.json());
const EXPORT_DIR = path.join(__dirname, 'public', 'exports');

// 报表导出服务：按用户提交的配置生成 HTML 报表文件，供在线预览与下载
app.post('/api/report/export', (req: express.Request, res: express.Response) => {
  // 入口1：报表标题，来自请求体，用户完全可控
  const title = String(req.body?.title ?? '未命名报表');
  // 入口2：筛选条件说明，用户可控
  const filterDesc = String(req.body?.filterDesc ?? '');
  // 入口3：数据行数组，用户可控
  const rows: string[] = Array.isArray(req.body?.rows) ? req.body.rows : [];

  // 直接拼接 HTML，未调用任何转义或净化函数
  let html = '<html><head><meta charset="utf-8"></head><body>';
  html += `<h2>${title}</h2>`;
  html += `<div class="filter">${filterDesc}</div>`;
  html += '<table border="1">';
  for (const row of rows) {
    html += `<tr><td>${row}</td></tr>`;
  }
  html += '</table></body></html>';

  const file = `report_${Date.now()}.html`;
  fs.writeFileSync(path.join(EXPORT_DIR, file), html); // sink：未转义的用户输入随报表落盘
  // 导出目录被静态托管，访问 previewUrl 即在浏览器中渲染报表内容
  res.json({ previewUrl: `/static/exports/${file}` });
});

app.use('/static/exports', express.static(EXPORT_DIR));
app.listen(8080);
