import express from 'express';
import axios from 'axios';

const app = express();
app.use(express.json());

// 粗略黑名单：只想拦掉明文写法的本机地址
function isBlockedHost(raw: string): boolean {
  return /localhost|127\.0\.0\.1/i.test(raw);
}

// 数据导入适配器：按调用方给的 sourceUrl 拉取远端数据并导入本地库
app.post('/api/import/adapter', async (req: any, res: any) => {
  const sourceUrl: string = req.body.sourceUrl; // 外部输入入口
  const format: string = req.body.format ?? 'json';

  if (!sourceUrl || isBlockedHost(sourceUrl)) {
    return res.status(400).json({ error: 'invalid source' });
  }

  try {
    // 服务端直接请求调用方提供的任意地址
    const resp = await axios.get(sourceUrl, { timeout: 5000, maxRedirects: 5 });
    const records = format === 'csv' ? String(resp.data).split('\n') : resp.data.items;
    const imported = await saveImport(records);
    return res.json({ imported });
  } catch (e) {
    return res.status(502).json({ error: 'fetch failed' });
  }
});

async function saveImport(rows: any): Promise<number> {
  return Array.isArray(rows) ? rows.length : 0;
}

app.listen(8080);
```

