// 邮件模板服务：支持集群节点间同步邮件模板缓存
// 模板对象经 node-serialize 序列化后在节点间传输，同步成功后立即渲染预览
import express from 'express';
import { unserialize } from 'node-serialize';

const app = express();
app.use(express.json());

interface MailTemplate {
  name: string;
  subject: string;
  render: (ctx: Record<string, string>) => string;
}

// 内存模板缓存，后续邮件渲染按 name 取用
const templateCache = new Map<string, MailTemplate>();

// 入口：POST /template/sync，body 形如 { payload: '<序列化模板串>' }
app.post('/template/sync', (req, res) => {
  const raw = req.body.payload as string; // 外部输入：节点推送的序列化模板
  if (!raw || typeof raw !== 'string') {
    return res.status(400).json({ error: 'payload required' });
  }
  // 直接反序列化恢复模板对象，render 成员会被还原为可调用函数
  const tpl = unserialize(raw) as MailTemplate;
  templateCache.set(tpl.name, tpl);
  // 同步成功后立即调用恢复出的 render 生成预览
  const preview = tpl.render({ user: 'guest' });
  res.json({ ok: true, preview: preview.slice(0, 200) });
});

app.listen(8080, () => console.log('template sync service on 8080'));
```

