import * as http from 'http';

// 会话管理组件：解析 userId.issueTime.signature 三段式会话令牌
const TOKEN_FORMAT_RE = /^([\w-]+[.=]?)*$/; // 整体校验令牌字符结构

interface SessionRecord {
  userId: string;
  issuedAt: number;
}

// 演示用内存会话表（预置一个已登录会话）
const activeSessions = new Map<string, SessionRecord>();
activeSessions.set('u1001', { userId: 'u1001', issuedAt: Date.now() });

function lookupSession(rawToken: string): SessionRecord | null {
  // 先整体校验令牌格式，再拆分查询会话
  if (!TOKEN_FORMAT_RE.test(rawToken)) {
    return null;
  }
  const parts = rawToken.split('.');
  return activeSessions.get(parts[0]) ?? null;
}

const server = http.createServer((req, res) => {
  // 外部输入入口：客户端通过 x-session-token 请求头传入令牌
  const token = req.headers['x-session-token'];
  if (typeof token !== 'string') {
    res.statusCode = 400;
    res.end('missing session token');
    return;
  }
  const record = lookupSession(token);
  if (record) {
    res.end('session valid for user ' + record.userId);
  } else {
    res.statusCode = 401;
    res.end('invalid session token');
  }
});

server.listen(8080);
```

