import { Channel, ConsumeMessage } from 'amqplib';
import { exec } from 'child_process';

// 消息队列消费者：处理上游投递的视频转码任务
// 预期消息体为 JSON，含 fileId 与 outputFormat 两个字段
const QUEUE = 'media.transcode.jobs';

export async function startTranscodeConsumer(channel: Channel): Promise<void> {
  await channel.assertQueue(QUEUE, { durable: true });
  channel.consume(QUEUE, (msg: ConsumeMessage | null) => {
    if (!msg) return;
    try {
      const job = JSON.parse(msg.content.toString());
      // 直接拼接消息字段构造命令，未做任何过滤或转义
      const inputPath = `/data/uploads/${job.fileId}`;
      const cmd = `ffmpeg -i ${inputPath} -f ${job.outputFormat} /data/out/${job.fileId}.${job.outputFormat}`;
      exec(cmd, (err, stdout) => {
        if (err) {
          console.error('transcode failed:', err.message);
          channel.nack(msg, false, false);
          return;
        }
        console.log('transcode ok:', stdout.slice(0, 100));
        channel.ack(msg);
      });
    } catch (e) {
      channel.nack(msg, false, false);
    }
  }, { noAck: false });
}
