// 数据导入适配器：根据用户提供的来源地址拉取外部数据并转换为导入记录
import axios from 'axios';

interface ImportRequest {
  sourceUrl: string;            // 用户提交的数据源地址，直接来自请求体
  format: 'json' | 'csv';
}

interface ImportRecord {
  payload: Record<string, unknown>;
}

// 弱黑名单：仅拦截 localhost 与 127.0.0.1 两个字面量
function isBlockedHost(url: URL): boolean {
  const host = url.hostname;
  return host === 'localhost' || host === '127.0.0.1';
}

// 入口：导入任务处理器，sourceUrl 为外部输入
export async function runImportTask(req: ImportRequest): Promise<ImportRecord[]> {
  const url = new URL(req.sourceUrl.trim());
  if (isBlockedHost(url)) {
    throw new Error('不允许的数据源');
  }
  // sink：以用户可控 URL 发起服务端 HTTP 请求
  const resp = await axios.get(url.toString(), { responseType: 'text', timeout: 8000 });
  const raw = resp.data as string;
  if (req.format === 'json') {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [parsed];
  }
  // csv 格式按行拆分为导入记录
  return raw.split('\n').filter(Boolean).map(line => ({ payload: { line } }));
}
