import * as http from 'http';

// 会话令牌形如多段 Base64url 片段,允许以点分隔(模拟 JWT 风格)
const SESSION_TOKEN_PATTERN = /^([A-Za-z0-9_-]+\.?)+$/;

// 内存会话表:token -> userId
const sessions = new Map<string, string>();

export function createSession(userId: string): string {
  const token = Buffer.from(userId).toString('base64url') + '.' + Date.now().toString(36);
  sessions.set(token, userId);
  return token;
}

// 入口:HTTP 请求处理器,从 Cookie 头提取 sid 并做格式校验
export function handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
  const cookie = req.headers.cookie ?? '';
  const pair = cookie.split(';').map(p => p.trim()).find(p => p.startsWith('sid=')) ?? '';
  const token = pair.slice(4); // 未限制长度、未过滤字符,直接进入校验
  if (!SESSION_TOKEN_PATTERN.test(token)) { // 攻击者可控输入到达正则引擎
    res.writeHead(401).end('invalid session token');
    return;
  }
  const userId = sessions.get(token);
  if (!userId) { res.writeHead(401).end('unknown session'); return; }
  res.writeHead(200).end('hello ' + userId);
}
