import amqp from 'amqplib';
import { exec } from 'child_process';

// 消息队列消费者：处理用户上传文件的归档任务
interface ArchiveTask {
  taskId: string;
  fileName: string;   // 用户上传的文件名，由外部生产者投递
  targetDir: string;  // 目标归档目录
}

async function startConsumer(): Promise<void> {
  const conn = await amqp.connect(process.env.RABBITMQ_URL!);
  const channel = await conn.createChannel();
  await channel.assertQueue('archive.tasks');

  channel.consume('archive.tasks', (msg) => {
    if (!msg) return;
    const task: ArchiveTask = JSON.parse(msg.content.toString()); // 外部输入入口
    // 直接拼接 shell 命令执行归档移动
    const cmd = `mv /tmp/uploads/${task.fileName} ${task.targetDir}`;
    exec(cmd, (err) => { // 命令执行点
      if (err) {
        console.error(`task ${task.taskId} failed: ${err.message}`);
        return;
      }
      channel.ack(msg);
    });
  }, { noAck: false });
}

startConsumer();
