import * as http from 'http';

// 简易会话存储：sid -> 会话信息
const sessions = new Map<string, { userId: string; expiresAt: number }>();

// 会话 ID 格式：字母数字段，可由 - . _ 分隔
const SESSION_ID_RE = /^([a-zA-Z0-9]+[-._]?)+$/;

export function createSession(userId: string): string {
  const sid = `${userId}-${Date.now().toString(36)}`;
  sessions.set(sid, { userId, expiresAt: Date.now() + 3_600_000 });
  return sid;
}

// 入口：处理携带 Cookie 的 HTTP 请求
export function handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
  const raw = req.headers.cookie ?? '';
  const cookieHeader: string = Array.isArray(raw) ? raw.join(';') : raw;
  const m = /(?:^|;\s*)sid=([^;]*)/.exec(cookieHeader);
  const sid = m ? m[1] : '';

  // 先校验会话 ID 格式，再查会话表（无长度上限、无超时保护）
  if (!SESSION_ID_RE.test(sid)) {
    res.statusCode = 401;
    res.end('invalid session id');
    return;
  }
  const sess = sessions.get(sid);
  if (!sess || sess.expiresAt < Date.now()) {
    res.statusCode = 401;
    res.end('unauthorized');
    return;
  }
  res.end(`hello ${sess.userId}`);
}
