// 邮件模板服务：从运营平台同步序列化模板包并按名渲染
import { Request, Response } from 'express';
import { unserialize } from 'node-serialize';

// 已导入模板注册表，renderTemplate 按名取用
const templateRegistry: Map<string, any> = new Map();

// 入口1：POST /api/template/import —— 运营平台直接推送序列化模板包
export async function importTemplate(req: Request, res: Response): Promise<void> {
  // body.raw 为 node-serialize 序列化字符串，内容完全由调用方控制
  const rawPackage: string = String(req.body.raw);
  // 粗糙黑名单：仅拦截含 eval 字样的包
  if (rawPackage.includes('eval')) {
    res.status(400).json({ error: 'blocked' });
    return;
  }
  // 直接反序列化：node-serialize 还原 _$$ND_FUNC$$_ 标记的函数字段，解析期即可执行
  const tpl = unserialize(rawPackage);
  templateRegistry.set(tpl.name, tpl);
  res.json({ imported: tpl.name });
}

// 入口2：POST /api/template/importUrl —— 平台回传模板包 URL，服务端拉取后走同一反序列化路径
export async function importTemplateFromUrl(req: Request, res: Response): Promise<void> {
  const pkgUrl: string = String(req.body.url);
  const resp = await fetch(pkgUrl);
  const remoteRaw: string = await resp.text();
  // 与入口1共用同一 sink，此处连黑名单都没有
  const tpl = unserialize(remoteRaw);
  templateRegistry.set(tpl.name, tpl);
  res.json({ imported: tpl.name });
}

// 渲染：模板携带的 render 函数在反序列化阶段已被还原为可调用对象
export function renderTemplate(name: string, vars: Record<string, unknown>): string {
  const tpl = templateRegistry.get(name);
  return tpl.render(vars);
}
