// 消息队列消费者:监听 media.transcode 队列,按消息指令执行视频转码
import * as amqp from 'amqplib';
import { exec } from 'child_process';

const QUEUE = 'media.transcode';

async function startConsumer(): Promise<void> {
  const conn = await amqp.connect('amqp://localhost');
  const channel = await conn.createChannel();
  await channel.assertQueue(QUEUE);

  // 上游服务投递的每条消息携带待转码文件名与目标格式
  channel.consume(QUEUE, async (msg) => {
    if (!msg) return;
    const payload = JSON.parse(msg.content.toString());
    const inputFile = payload.file;                 // 外部输入入口
    const outFormat = payload.format || 'mp4';

    // 直接拼接 ffmpeg 命令行并交给 shell 执行
    const cmd = `ffmpeg -i /uploads/${inputFile} -f ${outFormat} /out/${inputFile}.${outFormat}`;
    exec(cmd, (err, stdout) => {
      if (err) {
        console.error('转码失败:', err.message);
        channel.nack(msg);
        return;
      }
      console.log('转码输出:', stdout.slice(0, 100));
      channel.ack(msg);
    });
  });
}

startConsumer();
