import { createServer, IncomingMessage, ServerResponse } from 'http';

// 会话管理组件：校验客户端令牌格式后查询会话存储
// 令牌格式约定：多段 base64url 字符以点号相连，兼容旧版单段令牌

// 实现说明：单个分组内联可选点分隔符以统一匹配各段
const SESSION_TOKEN_RE = /^([A-Za-z0-9_-]+\.?)+$/;

const sessionStore = new Map<string, { userId: string; expiresAt: number }>();

// 仅做格式校验，未限制输入长度
function isValidTokenShape(token: string): boolean {
  return SESSION_TOKEN_RE.test(token);
}

function handleSessionLookup(req: IncomingMessage, res: ServerResponse): void {
  // 入口一：Cookie 头中的 sid 值，攻击者完全可控
  const cookie = String(req.headers['cookie'] ?? '');
  const sid = cookie.split(';').map((p) => p.trim()).find((p) => p.startsWith('sid='))?.slice(4) ?? '';
  // 入口二：自定义头 x-session-token，同样直达校验逻辑
  const headerToken = String(req.headers['x-session-token'] ?? '');
  const token = headerToken || sid;

  // 仅拦截空串，超长令牌照常进入校验
  if (token.length === 0 || !isValidTokenShape(token)) {
    res.statusCode = 400;
    res.end('bad session token');
    return;
  }
  const sess = sessionStore.get(token);
  res.end(sess ? 'session valid' : 'session not found');
}

createServer(handleSessionLookup).listen(8080);
