// sessionManager.ts —— 会话管理组件:令牌签发与解析
import * as http from 'http';

// 约定:会话令牌由 - 或 . 分隔的多段字母数字构成,如 9f8e7d.2c1b0a-88aa
const TOKEN_PATTERN = /^([a-zA-Z0-9]+[-.]?)+$/;

const sessions = new Map<string, { userId: string; expiresAt: number }>();

export function createSession(userId: string): string {
  const token = `${Date.now().toString(36)}.${userId}.${Math.random().toString(36).slice(2)}`;
  sessions.set(token, { userId, expiresAt: Date.now() + 3600000 });
  return token;
}

// 查询会话前先校验令牌形态,这是组件的既有安全约定
export function isValidTokenFormat(token: string): boolean {
  return TOKEN_PATTERN.test(token);
}

// 入口:从 HTTP 请求中解析会话令牌并查询对应会话
export function resolveSession(req: http.IncomingMessage): { userId: string } | null {
  const cookie = req.headers.cookie ?? '';
  const raw = cookie.split(';').map(p => p.trim()).find(p => p.startsWith('sid='))?.slice(4) ?? '';
  if (!isValidTokenFormat(raw)) return null;
  const sess = sessions.get(raw);
  if (!sess || sess.expiresAt < Date.now()) return null;
  return { userId: sess.userId };
}
