import * as fs from 'fs';
import * as path from 'path';

// 订单处理后台任务：消费队列投递的退款导入作业
interface RefundJob {
  orderId: string;
  merchantId?: string; // 外部输入：商户标识
  fileName: string; // 外部输入：退款明细文件名，取自消息体
}

const BASE_DIR = '/data/order-batch';

// 后台任务入口：队列 worker 收到原始消息后调用，payload 完全外部可控
export function processRefundJob(payload: string): { orderId: string; total: number } {
  const job: RefundJob = JSON.parse(payload);

  // 仅校验非空与类型，未限制路径字符
  if (!job.fileName || typeof job.fileName !== 'string') {
    throw new Error('fileName required');
  }

  // 拼接批量目录与外部文件名
  const filePath = path.join(BASE_DIR, job.merchantId ?? 'default', job.fileName);

  // 读取明细文件并汇总退款金额
  const raw = fs.readFileSync(filePath, 'utf-8');
  const rows: Array<{ amount: number }> = JSON.parse(raw);
  const total = rows.reduce((s, r) => s + Number(r.amount), 0);

