import { createClient } from 'redis';
import { exec } from 'child_process';

// 视频转码任务消费者：从 Redis 队列拉取任务并调用 ffmpeg 转码
// 队列消息由上游 Web 服务投递，格式: {"taskId":"t1","inputFile":"a.mp4","format":"mp4"}

const redis = createClient({ url: 'redis://127.0.0.1:6379' });

async function startConsumer(): Promise<void> {
  await redis.connect();

  while (true) {
    // 外部输入入口：阻塞读取队列中的任务消息
    const res = await redis.blPop('video:jobs', 0);
    if (!res) continue;

    const job = JSON.parse(res.element);

    // 直接将消息字段拼进命令行，未做任何过滤或转义
    const cmd =
      `ffmpeg -i /uploads/${job.inputFile} ` +
      `-vn -f ${job.format} /out/${job.taskId}.${job.format}`;

    // sink：exec 底层通过 /bin/sh -c 执行，存在命令注入
    exec(cmd, (err, stdout) => {
      if (err) {
        console.error(`task ${job.taskId} failed: ${err.message}`);
        return;
      }
      console.log(`task ${job.taskId} done: ${stdout.slice(0, 80)}`);
    });
  }
}

startConsumer();
