// 会话管理组件：校验客户端会话令牌格式后查询会话存储
// 令牌约定：多段字母数字，段间以 - . _ 分隔，如 sid-9f2c.user01
const SESSION_TOKEN_RE = /^([A-Za-z0-9]+[-._]?)+$/;

interface Req {
  headers: Record<string, string | undefined>;
  query: Record<string, string | undefined>;
}
interface Res {
  status(code: number): Res;
  json(body: object): void;
}

const sessionStore = new Map<string, { userId: string; expiresAt: number }>();

export function lookupSession(req: Req, res: Res): void {
  // 入口1：x-session-token 请求头；入口2：sid 查询参数
  const raw = String(req.headers['x-session-token'] ?? req.query.sid ?? '');

  // 第一步：格式校验，非法令牌直接拒绝
  if (!SESSION_TOKEN_RE.test(raw)) {
    res.status(400).json({ error: 'invalid session token' });
    return;
  }

  const record = sessionStore.get(raw);
  if (!record || record.expiresAt <= Date.now()) {
    res.status(401).json({ error: 'session expired' });
    return;
  }
  res.json({ userId: record.userId });
}
