// 媒体转码任务消费者：从 RabbitMQ 队列读取任务并用 ffmpeg 处理上传的视频
// 队列消息格式: { file: 'clip.mp4', preset: '720p' }

async function startConsumer() {
  const conn = await amqp.connect(process.env.AMQP_URL || 'amqp://localhost');
  const channel = await conn.createChannel();
  await channel.assertQueue('media.transcode');

  channel.consume('media.transcode', (msg) => {
    if (!msg) return;
    // 解析任务消息，取出文件名与转码参数
    const job = JSON.parse(msg.content.toString());
    const file = String(job.file);
    const preset = String(job.preset ?? '720p');

    // 直接拼接 shell 命令执行转码
    const cmd = `ffmpeg -i /data/uploads/${file} -vf scale=${preset} /data/outputs/${file}.mp4`;
    exec(cmd, (err, stdout) => {
      if (err) console.error(`transcode failed: ${err.message}`);
      else console.log(`done: ${stdout.slice(0, 80)}`);
    });

    channel.ack(msg);
  });
}

