import express from 'express';

const app = express();

// 会话令牌格式：<base64url-id>.<base64url-signature>，段内允许出现 '/'（兼容旧版编码）
const TOKEN_RE = /^([\w-]+\/?)+\.([\w-]+\/?)+$/;

// 内存会话表：sessionId -> 会话数据
const sessionStore = new Map<string, { userId: string; expiresAt: number }>();

// 解析请求头中的会话令牌：先做格式校验，再查会话表
function resolveSession(req: express.Request): { userId: string } | null {
  const raw = String(req.headers['x-session-token'] ?? '');
  if (raw.length > 0 && TOKEN_RE.test(raw)) {
    const id = raw.split('.')[0];
    const sess = sessionStore.get(id);
    if (sess && sess.expiresAt > Date.now()) {
      return { userId: sess.userId };
    }
  }
  return null;
}

// 个人资料接口：未携带有效会话则返回 401
app.get('/api/profile', (req, res) => {
  const session = resolveSession(req);
  if (!session) {
    res.status(401).json({ error: 'unauthorized' });
    return;
  }
  res.json({ userId: session.userId });
});

app.listen(8080, () => console.log('listening on 8080'));
```

