import { createClient } from 'redis';
import { exec } from 'child_process';

// 消息队列消费者：处理用户上传视频的转码任务
const redis = createClient({ url: 'redis://127.0.0.1:6379' });

interface TranscodeJob {
  taskId: string;
  inputFile: string;  // 来自用户上传请求的原始文件名
  format: string;     // 用户指定的目标格式
}

function execAsync(cmd: string): Promise<string> {
  return new Promise((resolve, reject) => {
    exec(cmd, (err, stdout) => (err ? reject(err) : resolve(stdout)));
  });
}

async function handleJob(job: TranscodeJob): Promise<void> {
  // 仅去除空白字符，未过滤分号、竖线、$() 等 shell 元字符
  const name = job.inputFile.trim().replace(/\s+/g, '');
  const cmd = `ffmpeg -i /data/uploads/${name} -f ${job.format} /data/out/${job.taskId}.${job.format}`;
  await execAsync(cmd);
}

async function startConsumer(): Promise<void> {
  await redis.connect();
  while (true) {
    // 队列消息由上游 Web API 写入，字段值完全来自外部用户请求
    const raw = await redis.lPop('transcode:jobs');
    if (!raw) { await new Promise(r => setTimeout(r, 500)); continue; }
    const job = JSON.parse(raw) as TranscodeJob;
    await handleJob(job);
  }
}

startConsumer();
