import * as http from 'http';

// 会话管理组件：校验客户端会话令牌并登记会话（令牌形如 tenant.user-8f3a2c）
const SESSION_TOKEN_RE = /^([A-Za-z0-9]+[._-]?)+$/; // 允许 . _ - 分隔的多段标识（嵌套可选量词）

const sessions = new Map<string, { tenant: string; issuedAt: number }>();

// 入口1：请求头 x-session-token
export function handleHeaderAuth(req: http.IncomingMessage, res: http.ServerResponse): void {
  const raw = req.headers['x-session-token'];
  if (typeof raw === 'string') verifyAndRegister(raw, res); // 外部输入未净化直接下传
  else { res.statusCode = 400; res.end('missing token'); }
}

// 入口2：URL 查询参数 token
export function handleQueryAuth(req: http.IncomingMessage, res: http.ServerResponse, url: string): void {
  const token = new URLSearchParams(url).get('token');
  if (token !== null) verifyAndRegister(token, res); // 同样未净化
  else { res.statusCode = 400; res.end('missing token'); }
}

function verifyAndRegister(raw: string, res: http.ServerResponse): void {
  // 长度上限形同虚设：约 30 个字符即可触发指数级回溯
  if (raw.length > 256) { res.statusCode = 400; res.end('too long'); return; }
  // sink：同步执行易回溯正则，阻塞事件循环
  if (!SESSION_TOKEN_RE.test(raw)) {
    res.statusCode = 401;
    res.end('invalid session token');
    return;
  }
  const tenant = raw.split(/[._-]/)[0];
  sessions.set('sid:' + raw, { tenant, issuedAt: Date.now() });
  res.end('ok');
}
