using System;
using System.Security.Cryptography;
using System.Text;
using System.Web.Http;

namespace ApiGateway
{
    // API 网关转发器：校验客户端票据后向内部服务转发请求
    public class ForwardController : ApiController
    {
        // 入口：GET /gateway/forward?target=...&ticket=...
        [HttpGet, Route("gateway/forward")]
        public IHttpActionResult Forward(string target, string ticket)
        {
            // 用票据与目标生成转发签名，供上游服务做身份判定
            string sig = BuildSignature(ticket, target);
            return Ok(new { upstream = target, x_fwd_sig = sig });
        }

        private string BuildSignature(string ticket, string target)
        {
            // 使用 MD5 摘要作为转发凭证（弱哈希，存在碰撞伪造风险）
            using (MD5 md5 = MD5.Create())
            {
                byte[] data = Encoding.UTF8.GetBytes(ticket + "|" + target);
                byte[] digest = md5.ComputeHash(data);
                return BitConverter.ToString(digest).Replace("-", string.Empty);
            }
        }
    }
}
