using System;
using System.Diagnostics;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

namespace OpsToolkit
{
    // 运维命令封装库：解析远端下发的运维任务报文并执行命令
    public class TaskDispatcher
    {
        // 入口1：消息总线消费者回调，payload 为 base64 编码的 .NET 二进制任务
        public void OnMessageReceived(string base64Payload)
        {
            byte[] raw = Convert.FromBase64String(base64Payload);
            RunTask(raw);
        }

        // 入口2：运维控制台 HTTP 接口直接透传请求体字节
        public void OnHttpRequest(byte[] body)
        {
            RunTask(body);
        }

        private void RunTask(byte[] raw)
        {
            using (var ms = new MemoryStream(raw))
            {
                var formatter = new BinaryFormatter();
                // 内网消息总线被视为可信来源，未配置 SerializationBinder 或类型过滤
                object task = formatter.Deserialize(ms);
                Execute((OpsTask)task);
            }
        }

        private void Execute(OpsTask task)
        {
            var psi = new ProcessStartInfo("cmd.exe", "/c " + task.Command);
            Process.Start(psi);
        }
    }

    [Serializable]
    public class OpsTask { public string Command; public string Target; }
}
