    // 权限校验中间件：解析客户端提交的 XML 授权声明，校验角色后决定放行
    public class PermissionMiddleware
    {
        public bool Authorize(HttpRequest request)
        {
            // 入口：请求体即外部输入，未经任何过滤直接进入解析流程
            string xmlBody = new StreamReader(request.InputStream).ReadToEnd();

