            XmlNode roleNode = doc.SelectSingleNode("//authorization/role");
            if (roleNode == null)
            {
                return false;
            }

            // 仅比对角色字符串，未限制 DOCTYPE，也未禁用实体展开
            return roleNode.InnerText == "admin";
        }
    }
