    private static readonly HttpClient Http = new HttpClient();

    // 入口：GET /webhook/send?targetUrl=...&eventLabel=...（网关将请求路由到本处理器）
    public async Task HandleSend(HttpListenerContext ctx)
    {
        // 外部输入：订阅方回调地址与事件标签，均直接取自请求查询串
        string targetUrl = ctx.Request.QueryString["targetUrl"];
        string eventLabel = ctx.Request.QueryString["eventLabel"];

        // 组装事件载荷并向订阅方出站投递
        string payload = "{\"event\":\"" + eventLabel + "\",\"ts\":\"" + DateTime.UtcNow.ToString("o") + "\"}";
        var resp = await Http.PostAsync(targetUrl, new StringContent(payload, Encoding.UTF8, "application/json"));
        string remoteBody = await resp.Content.ReadAsStringAsync(); // 间接输入：订阅方响应体

        // 渲染投递报告页：字符串直接拼接，未做任何 HTML 实体编码
        ctx.Response.ContentType = "text/html; charset=utf-8";
        var html = new StringBuilder("<html><body><h3>Webhook 投递报告</h3>");
        html.Append("<p>事件: ").Append(eventLabel).Append("</p>");
        html.Append("<p>目标: <a href='").Append(targetUrl).Append("'>").Append(targetUrl).Append("</a></p>");
        html.Append("<pre>响应: ").Append(remoteBody).Append("</pre></body></html>");
        byte[] buf = Encoding.UTF8.GetBytes(html.ToString());
        await ctx.Response.OutputStream.WriteAsync(buf, 0, buf.Length);
    }
