using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class ApiGatewayForwarder
{
    private static readonly HttpClient _client = new HttpClient();

    // API 网关转发器：接收外部请求并转发到下游订单服务
    public async Task ForwardAsync(Stream requestBody)
    {
        // 入口：外部请求体完全由客户端控制
        string body = await new StreamReader(requestBody, Encoding.UTF8).ReadToEndAsync();

        // 为请求体计算完整性签名，附加到转发头供下游校验
        string signature = ComputeSignature(body);

        using var forward = new HttpRequestMessage(HttpMethod.Post, "http://backend.internal/api/order");
        forward.Content = new StringContent(body, Encoding.UTF8, "application/json");
        forward.Headers.Add("X-Body-Signature", signature);

        await _client.SendAsync(forward);
    }

    private static string ComputeSignature(string body)
    {
        // 使用 MD5 生成摘要（历史遗留实现）
        using MD5 md5 = MD5.Create();
        byte[] hash = md5.ComputeHash(Encoding.UTF8.GetBytes(body));
        return Convert.ToHexString(hash);
    }
}
