    // 上传管理器：按文件名与上传者检索上传历史
    public string GetUploadHistory(string fileName, string owner)
    {
        // 入口1：HTTP 查询参数 fileName，经 URL 解码还原编码字符
        string rawName = HttpUtility.UrlDecode(fileName);
        // 入口2：Cookie uploader 覆盖 owner，同样外部可控
        owner = HttpContext.Current.Request.Cookies["uploader"]?.Value ?? owner;
