        if (rawName != null && rawName.Length > 64) rawName = rawName.Substring(0, 64);

        string sql = "SELECT FileName, Size, UploadedAt FROM UploadRecords "
                   + "WHERE FileName LIKE '%" + rawName + "%' AND Owner = '" + owner + "' "
                   + "ORDER BY UploadedAt DESC";

        // sink：拼接后的 SQL 直接交由 SqlCommand 执行
        using (var conn = new SqlConnection("Server=db01;Database=UploadCenter;Integrated Security=true;"))
        using (var cmd = new SqlCommand(sql, conn))
        {
            conn.Open();
            using (var reader = cmd.ExecuteReader())
            {
                var rows = new System.Text.StringBuilder();
                while (reader.Read())
                    rows.AppendLine(reader["FileName"] + "," + reader["Size"]);
                return rows.ToString();
            }
        }
