import express from 'express';
import { unserialize } from 'node-serialize';

const app = express();
app.use(express.json());

// 邮件模板服务：上游营销平台将模板配置（含动态正文构造函数）序列化后随请求下发，
// 服务端反序列化还原配置，并调用其中的函数渲染邮件正文
interface MailTemplate {
  subject: string;
  buildBody: (ctx: Record<string, unknown>) => string;
}

app.post('/mail/render', (req, res) => {
  // 入口：序列化模板串经请求体 config 字段直接传入，外部完全可控
  const raw = String(req.body?.config ?? '');
  if (!raw) return res.status(400).json({ error: 'config required' });

  // 仅做 base64 解码，未附加签名/HMAC 等完整性校验
  const serialized = Buffer.from(raw, 'base64').toString('utf8');

  // node-serialize 会还原 _$$ND_FUNC$$_ 标记的函数成员，内嵌 IIFE 在反序列化时即被执行
  const tpl = unserialize(serialized) as MailTemplate;

  // 渲染阶段再次调用还原出的函数，构成第二触发点
  const html = `<div>${tpl.buildBody({ user: req.body?.user })}</div>`;
  res.json({ subject: tpl.subject, html });
});

app.listen(3000, () => console.log('mail-template service on :3000'));
