using System;
using System.Xml;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;

// 权限校验中间件：解析请求头中的 XML 授权断言，校验角色后放行
public class PermissionCheckMiddleware
{
    private readonly RequestDelegate _next;
    public PermissionCheckMiddleware(RequestDelegate next) { _next = next; }

    public async Task InvokeAsync(HttpContext ctx)
    {
        // 入口：外部输入来自请求头 X-Auth-Ticket，完全由客户端控制
        string ticket = ctx.Request.Headers["X-Auth-Ticket"].ToString();
        if (string.IsNullOrEmpty(ticket)) { ctx.Response.StatusCode = 401; return; }

        XmlDocument doc = new XmlDocument();
        // 为兼容旧网关的内联 DTD 票据格式，显式启用外部实体解析
        doc.XmlResolver = new XmlUrlResolver();   // 危险：允许解析 file:// 与 http:// 外部实体
        try
        {
            doc.LoadXml(ticket);                  // sink：XXE 触发点
        }
        catch (XmlException ex)
        {
            ctx.Response.StatusCode = 400;
            await ctx.Response.WriteAsync(ex.Message); // 解析异常回显，可泄露实体内容
            return;
        }

        string role = doc.SelectSingleNode("//Assertion/Role")?.InnerText ?? "";
        if (role != "admin")
        {
            // 拒绝时回显角色值：若 Role 为外部实体，目标文件内容被直接返回
            ctx.Response.StatusCode = 403;
            await ctx.Response.WriteAsync("Access denied for role: " + role);
            return;
        }
        await _next(ctx);
    }
}
