using System.Xml;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;

public class PermissionCheckMiddleware
{
    private readonly RequestDelegate _next;
    public PermissionCheckMiddleware(RequestDelegate next) { _next = next; }

    // 权限校验中间件：解析 POST 请求体中的 XML 权限断言，校验角色后放行
    public async Task InvokeAsync(HttpContext context)
    {
        // 入口：外部请求体，客户端完全可控
        using var reader = new StreamReader(context.Request.Body, Encoding.UTF8);
        string assertion = await reader.ReadToEndAsync();
        if (string.IsNullOrEmpty(assertion))
        {
            context.Response.StatusCode = 401;
            return;
        }

        // 解析 XML 权限断言并提取 <role> 节点
        XmlDocument doc = new XmlDocument();
        doc.XmlResolver = new XmlUrlResolver(); // 允许解析 DTD 与外部实体
        doc.LoadXml(assertion);

        string role = doc.SelectSingleNode("//role")?.InnerText ?? "";
        if (role != "admin" && role != "operator")
        {
            context.Response.StatusCode = 403;
            return;
        }
        await _next(context);
    }
}
