using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

// API 网关转发器：接收外部请求并转发到内部微服务
[ApiController]
[Route("api/gw")]
public class ApiGatewayForwarder : ControllerBase
{
    private readonly IHttpClientFactory _httpFactory;
    // 网关与后端共享的转发签名密钥，仅从部署环境注入
    private static readonly string SignSecret = Environment.GetEnvironmentVariable("GW_FORWARD_SECRET");

    public ApiGatewayForwarder(IHttpClientFactory httpFactory) => _httpFactory = httpFactory;

    // 入口：外部客户端可完全控制 service 路径段与 body 内容
    [HttpPost("{service}")]
    public async Task<IActionResult> Forward(string service, [FromBody] string body)
    {
        // 生成转发签名供后端校验请求完整性（防篡改）
        using var md5 = MD5.Create(); // 弱哈希：MD5 已被证明存在实用碰撞攻击
        string material = service + "|" + body + "|" + SignSecret;
        byte[] digest = md5.ComputeHash(Encoding.UTF8.GetBytes(material));
        string signature = Convert.ToHexString(digest);

        var client = _httpFactory.CreateClient("backend");
        using var req = new HttpRequestMessage(HttpMethod.Post, "http://order-svc/" + service)
        {
            Content = new StringContent(body, Encoding.UTF8, "application/json")
        };
        req.Headers.Add("X-GW-Sign", signature);
        var resp = await client.SendAsync(req);
        return StatusCode((int)resp.StatusCode);
    }
}
