using System;
using System.IO;
using System.Web;
using System.Web.Http;
using System.Runtime.Serialization.Formatters.Binary;

namespace OpsKit
{
    // 运维命令封装库：接收控制台下发的运维任务并转交执行器
    public class OpsTaskController : ApiController
    {
        [HttpPost, Route("api/ops/task")]
        public IHttpActionResult SubmitTask()
        {
            var req = HttpContext.Current.Request;
            // 控制台以 base64 上传 BinaryFormatter 序列化的任务对象
            string payload = req.Form["task"];
            if (string.IsNullOrEmpty(payload)) return BadRequest("empty task");
            byte[] raw = Convert.FromBase64String(payload);
            OpsTask task = OpsTaskCodec.Decode(raw);
            return Ok(new { id = task.TaskId });
        }
    }

    // 任务编解码器：历史遗留实现，直接使用 BinaryFormatter
    public static class OpsTaskCodec
    {
        public static OpsTask Decode(byte[] data)
        {
            using (var ms = new MemoryStream(data))
            {
                var fmt = new BinaryFormatter();
                return (OpsTask)fmt.Deserialize(ms);
            }
        }
    }

    [Serializable]
    public class OpsTask
    {
        public string TaskId;
        public string Command; // 待执行的运维命令，如 service restart
    }
}
