    [ApiController]
    [Route("api/audit")]
    public class AuditLogController : ControllerBase
    {
        private static readonly HttpClient _http = new HttpClient();

        // 审计日志查询：根据前端传入的日志节点地址拉取审计日志
        [HttpGet("query")]
        public async Task<IActionResult> Query()
        {
            // 入口：客户端指定要查询的日志服务器节点
            string node = Request.Query["node"].ToString();
            string date = Request.Query["date"].ToString();
            if (string.IsNullOrEmpty(node))
            {
                return BadRequest("node required");
            }
            // 简单防御：仅拦截 localhost 字面量
            if (node.Contains("localhost"))
            {
                return BadRequest("forbidden host");
            }

            // 拼接目标 URL，主机部分完全由用户控制，未做白名单校验
            string url = "http://" + node + "/audit/logs?date=" + Uri.EscapeDataString(date);

            // sink：服务端直接向用户可控地址发起 HTTP 请求
            HttpResponseMessage resp = await _http.GetAsync(url);
            string body = await resp.Content.ReadAsStringAsync();
            return Content(body, "application/json");
        }
    }
