using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;

public class WebhookSender
{
    // 出站 webhook 发送器: 接收外部目标地址与消息体, 转发后回显投递结果页
    public async Task HandleSend(HttpContext ctx, HttpClient http)
    {
        // 入口1: 查询串中的目标 URL 与消息体
        string target = ctx.Request.Query["url"];
        string payload = ctx.Request.Query["payload"];
        // 入口2: 请求头中的租户标签, 用于结果页展示
        string tag = ctx.Request.Headers["X-Tenant-Tag"].ToString();

        string respBody = "(no response)";
        if (Uri.TryCreate(target, UriKind.Absolute, out var uri))
        {
            using var content = new StringContent(payload, Encoding.UTF8, "application/json");
            HttpResponseMessage resp = await http.PostAsync(uri, content);
            respBody = await resp.Content.ReadAsStringAsync(); // 远端返回体
        }

        // 结果页: 直接字符串拼接 URL、标签与远端响应体, 未做任何 HTML 编码
        ctx.Response.ContentType = "text/html; charset=utf-8";
        await ctx.Response.WriteAsync(
            "<html><body><h3>Webhook 投递结果</h3>" +
            "<p>目标: " + target + "</p>" +
            "<p>标签: " + tag + "</p>" +
            "<pre>" + respBody + "</pre></body></html>");
    }
}
