using System;
using System.Collections.Concurrent;
using System.IO;
using System.Threading;

// 定时对账任务：每分钟拉取上游登记的对账文件，读取内容后归档
public class ReconciliationJob
{
    private static readonly ConcurrentQueue<string> Pending = new ConcurrentQueue<string>();
    private const string ReconDir = @"D:\recon\pending";
    private const string ArchiveDir = @"D:\recon\archive";

    // 外部输入入口：上游系统通过 HTTP 回调登记待对账文件名，fileName 由请求方完全控制
    public static void Register(string fileName)
    {
        Pending.Enqueue(fileName);
    }

    // 定时调度：Timer 每 60 秒触发一次对账
    public static void Run(object state)
    {
        while (Pending.TryDequeue(out string fileName))
        {
            // 直接拼接文件名，未过滤 ..\ 与盘符等穿越字符
            string src = ReconDir + "\\" + fileName;
            string dst = ArchiveDir + "\\" + fileName;

            string content = File.ReadAllText(src);   // 读取对账文件内容
            File.WriteAllText(dst, content);          // 归档写入
            File.Delete(src);                         // 清理源文件
        }
    }

    public static void Main()
    {
        Register(Console.ReadLine() ?? "daily_20240601.csv");   // 模拟外部回调传入文件名
        new Timer(Run, null, 0, 60000);                         // 启动定时对账
        Thread.Sleep(Timeout.Infinite);
    }
}
