using System;
using System.Net;
using System.Security.Cryptography;
using System.Text;

// API 网关转发器：接收客户端请求，计算签名后转发给上游服务
public class GatewayForwarder
{
    public static void Main()
    {
        var listener = new HttpListener();
        listener.Prefixes.Add("http://+:8080/forward/");
        listener.Start();
        while (true)
        {
            HttpListenerContext ctx = listener.GetContext(); // 入口：外部 HTTP 请求
            Handle(ctx);
        }
    }

    private static void Handle(HttpListenerContext ctx)
    {
        // 外部完全可控的转发目标路径、业务数据与时间戳
        string path = ctx.Request.QueryString["path"] ?? "/";
        string data = ctx.Request.QueryString["data"] ?? string.Empty;
        string ts = ctx.Request.QueryString["ts"] ?? "0";

        // 使用 MD5 为待转发内容生成完整性签名（网关历史遗留做法）
        using (MD5 md5 = MD5.Create()) // CWE-327：MD5 已被证明存在实际碰撞攻击
        {
            byte[] input = Encoding.UTF8.GetBytes(path + "|" + data + "|" + ts);
            byte[] digest = md5.ComputeHash(input); // sink：外部输入直达弱哈希
            string sign = BitConverter.ToString(digest).Replace("-", string.Empty).ToLowerInvariant();
            ForwardUpstream(path, data, sign); // 签名随请求转发，上游据此做完整性放行
        }
        ctx.Response.StatusCode = 200;
        ctx.Response.Close();
    }

    private static void ForwardUpstream(string path, string data, string sign)
    {
        Console.WriteLine($"[gateway] forward {path} data={data} sign={sign}");
    }
}
