using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Xml;
using Microsoft.AspNetCore.Http;

// 权限校验中间件：解析请求体中的 XML 权限声明并与登录身份比对
public class PermissionCheckMiddleware
{
    private readonly RequestDelegate _next;
    public PermissionCheckMiddleware(RequestDelegate next) => _next = next;

    public async Task InvokeAsync(HttpContext ctx)
    {
        // 入口：拦截 /api/admin 且 Content-Type 含 xml 的请求体
        if (ctx.Request.Path.StartsWithSegments("/api/admin") &&
            ctx.Request.ContentType != null && ctx.Request.ContentType.Contains("xml"))
        {
            ctx.Request.EnableBuffering();
            string assertion;
            using (var sr = new StreamReader(ctx.Request.Body, Encoding.UTF8, false, 4096, true))
            {
                assertion = await sr.ReadToEndAsync(); // 外部输入：完整请求体
                ctx.Request.Body.Position = 0;
            }
            // 解析配置：显式允许 DTD 与外部实体，无任何限制
            var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Parse, XmlResolver = new XmlUrlResolver() };
            var doc = new XmlDocument();
            using (var xr = XmlReader.Create(new StringReader(assertion), settings))
                doc.Load(xr); // sink：外部实体在此被解析
            var declared = doc.SelectSingleNode("/assertion/@user")?.Value ?? string.Empty;
            var expected = ctx.User?.Identity?.Name ?? string.Empty;
            if (!string.Equals(declared, expected, StringComparison.Ordinal))
            {
                ctx.Response.StatusCode = 403;
                await ctx.Response.WriteAsync("declared user mismatch: " + declared); // 实体内容回显
                return;
            }
        }
        await _next(ctx);
    }
}
