{
    private const string ConnStr = "Server=localhost;Database=FileStore;Integrated Security=True;";

    // 入口：上传处理页面在收到 POST 请求后调用本方法
    public void SaveUploadRecord(HttpRequest request)
    {
        HttpPostedFile file = request.Files["attachment"];              // 外部输入1：上传文件对象
