using System;
using System.Diagnostics;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

namespace OpsKit
{
    // 运维命令封装库：接收远端控制台下发的序列化命令载荷并执行
    public class OpsCommandRunner
    {
        // 入口：由 HTTP 回调或消息队列消费者调用，payload 为 base64 编码的序列化命令
        public string Dispatch(string payloadBase64)
        {
            byte[] raw = Convert.FromBase64String(payloadBase64);
            object cmd = DeserializeCommand(raw);
            return ((OpsCommand)cmd).Execute();
        }

        // 反序列化：直接使用 BinaryFormatter 还原命令对象，未做类型约束与签名校验
        private object DeserializeCommand(byte[] raw)
        {
            BinaryFormatter bf = new BinaryFormatter();
            using (MemoryStream ms = new MemoryStream(raw))
            {
                return bf.Deserialize(ms);
            }
        }
    }

    [Serializable]
    public class OpsCommand
    {
        public string Tool;
        public string Args;

        public string Execute()
        {
            Process.Start(Tool, Args);
            return "done";
        }
    }
}
