using System;
using System.IO;
using System.Text;
using Microsoft.AspNetCore.Mvc;

namespace Settlement.Reconciliation
{
    // 定时对账任务：调度器每小时调用一次，也支持运维手动补跑历史账期
    [ApiController]
    [Route("api/recon")]
    public class ReconciliationController : ControllerBase
    {
        private const string ReconDir = @"D:\settle\recon\";

        // 对账入口：file 为对账流水文件名，channel 为渠道过滤关键字
        [HttpGet("run")]
        public IActionResult Run([FromQuery] string file, [FromQuery] string channel)
        {
            if (string.IsNullOrEmpty(file))
                return BadRequest("file required");

            // 弱防御：仅拦截相对穿越符，认为绝对路径只会由内部调度器传入
            if (file.Contains(".."))
                return BadRequest("illegal path");

            // Path.Combine 遇到盘符或 UNC 等 rooted 路径时会整体丢弃 ReconDir
            string path = Path.Combine(ReconDir, file);

            var report = new StringBuilder();
            foreach (string row in File.ReadAllLines(path)) // 对账流水逐行读取
            {
                if (row.Contains(channel ?? "ALL"))
                    report.AppendLine(row);
            }
            File.WriteAllText(ReconDir + "result_" + DateTime.Now.Hour + ".txt", report.ToString());
            return Ok("reconciliation finished");
        }
    }
}
