using System;
using System.Diagnostics;

// 日志归档工具：接收运维平台传入的日志文件名并调用系统 tar 命令压缩归档
class LogArchiver
{
    static void Main(string[] args)
    {
        // 入口1：命令行参数指定待归档日志名，缺省为 app.log
        string logName = args.Length > 0 ? args[0] : "app.log";
        string result = ArchiveLog(logName);
        Console.WriteLine(result);
    }

    // 入口2：供运维平台 RPC 直接调用的归档接口，logName 未做任何过滤
    public static string ArchiveLog(string logName)
    {
        // 拼接归档命令，期望形如：tar -czf /var/archive/app.log.tar.gz app.log
        string archivePath = "/var/archive/" + logName + ".tar.gz";
        string cmd = "tar -czf " + archivePath + " " + logName;

        var psi = new ProcessStartInfo();
        psi.FileName = "/bin/bash";
        // 通过 bash -c 执行，双引号包裹无法阻止分号与 $() 注入
        psi.Arguments = "-c \"" + cmd + "\"";
        psi.RedirectStandardOutput = true;
        psi.UseShellExecute = false;

        using (Process proc = Process.Start(psi)) // sink：命令注入点
        {
            proc.WaitForExit();
            return proc.StandardOutput.ReadToEnd();
        }
    }
}
