using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

// API 网关转发器：接收外部请求，附加完整性签名后转发到内部服务
[Route("api/gateway/forward")]
public class ForwardController : ControllerBase
{
    private static readonly HttpClient Http = new HttpClient();
    private const string UpstreamUrl = "http://internal-svc.local/handler";

    // 入口：POST /api/gateway/forward?ticket=xxx，请求体为待转发内容
    [HttpPost]
    public async Task<IActionResult> Forward([FromQuery] string ticket)
    {
        string body = await new StreamReader(Request.Body).ReadToEndAsync();

        // 网关用 MD5 生成转发签名，上游依赖该签名校验请求完整性
        using (var md5 = MD5.Create())
        {
            byte[] raw = Encoding.UTF8.GetBytes(ticket + "|" + body);
            byte[] digest = md5.ComputeHash(raw); // sink：MD5 为已破解的弱哈希
            string sig = BitConverter.ToString(digest).Replace("-", string.Empty);

            using (var req = new HttpRequestMessage(HttpMethod.Post, UpstreamUrl))
            {
                req.Headers.Add("X-Gateway-Signature", sig);
                req.Content = new StringContent(body, Encoding.UTF8, "application/json");
                await Http.SendAsync(req);
            }
        }
        return Ok();
    }
}
