using System.Threading.Tasks;
using System.Xml;
using Microsoft.AspNetCore.Http;

namespace Auth
{
    // 权限校验中间件：解析请求头中的 XML 权限断言，校验角色后放行
    public class PermissionCheckMiddleware
    {
        private readonly RequestDelegate _next;
        public PermissionCheckMiddleware(RequestDelegate next) { _next = next; }

        public async Task Invoke(HttpContext ctx)
        {
            // 入口：攻击者完全可控的 HTTP 请求头
            string assertion = ctx.Request.Headers["X-Perm-Assertion"].ToString();
            if (string.IsNullOrEmpty(assertion)) { ctx.Response.StatusCode = 401; return; }

            XmlDocument doc = new XmlDocument();
            doc.XmlResolver = new XmlUrlResolver(); // 显式开启外部实体解析
            doc.LoadXml(assertion);                 // 用户可控 XML 在此被解析

            string role = doc.SelectSingleNode("//Role")?.InnerText ?? "";
            if (role != "admin")
            {
                ctx.Response.StatusCode = 403;
                await ctx.Response.WriteAsync("denied role: " + role); // 解析结果回显
                return;
            }

            ctx.Items["role"] = role;
            await _next(ctx);
        }
    }
}
