using System;
using System.Net.Http;
using System.Text;
using System.Web;

public class WebhookDispatchModule : IHttpModule
{
    // 全局投递日志，/webhook/deliveries 页面直接输出
    static string LastDeliveryHtml = "<div>暂无投递记录</div>";

    public void Init(HttpApplication app) { app.BeginRequest += OnBegin; }

    private void OnBegin(object sender, EventArgs e)
    {
        var ctx = ((HttpApplication)sender).Context;
        if (ctx.Request.Path == "/webhook/dispatch")
        {
            // 入口：event 与 url 均取自查询字符串，外部完全可控
            string eventName = ctx.Request.QueryString["event"];
