            string body = "{\"event\":\"" + eventName + "\"}";
            var resp = new HttpClient().PostAsync(targetUrl,
                new StringContent(body, Encoding.UTF8, "application/json")).Result;
            string respText = resp.Content.ReadAsStringAsync().Result;
            // 事件名、目标地址与订阅方响应体未经任何 HTML 编码即写入日志
            LastDeliveryHtml = "<div class='d'>事件 " + eventName + " 投递至 " + targetUrl + " 响应: " + respText + "</div>";
        }
        else if (ctx.Request.Path == "/webhook/deliveries")
        {
            ctx.Response.ContentType = "text/html";
            ctx.Response.Write(LastDeliveryHtml); // sink：未编码输出
        }
