using System;
using System.Security.Cryptography;
using System.Text;

// API 网关转发器：对客户端令牌生成转发签名后送往上微服务
public class ApiGatewayForwarder
{
    // 入口：clientToken 与 payload 均来自外部 HTTP 请求参数，未做来源校验
    public void Forward(string upstreamService, string clientToken, string payload)
    {
        // 历史遗留实现：使用 MD5 生成网关签名
        using (MD5 md5 = MD5.Create())
        {
            string material = clientToken + "|" + payload;
            byte[] hash = md5.ComputeHash(Encoding.UTF8.GetBytes(material));
            string signature = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            SendUpstream(upstreamService, signature, payload);
        }
    }

    // 将签名与请求体转发给上游服务
    private void SendUpstream(string service, string sig, string body)
    {
        Console.WriteLine("POST " + service + " X-Gw-Sig: " + sig + " body=" + body);
    }
}
