using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Xml;
using Microsoft.AspNetCore.Http;

// 权限校验中间件：解析请求携带的 XML 权限断言，决定是否放行受保护接口
public class PermissionCheckMiddleware
{
    private readonly RequestDelegate _next;
    public PermissionCheckMiddleware(RequestDelegate next) { _next = next; }

    // 入口：所有发往 /api/secure 的请求都经过本方法，请求体即外部输入
    public async Task InvokeAsync(HttpContext context)
    {
        if (!context.Request.Path.StartsWithSegments("/api/secure"))
        { await _next(context); return; }

        context.Request.EnableBuffering();
        using var reader = new StreamReader(context.Request.Body, Encoding.UTF8, false, 1024, leaveOpen: true);
        var assertionXml = await reader.ReadToEndAsync();      // 外部输入：客户端完全可控的 XML 断言
        context.Request.Body.Position = 0;

        var doc = new XmlDocument();
        doc.XmlResolver = new XmlUrlResolver();                // 防御缺失：显式启用外部实体解析
        doc.LoadXml(assertionXml);                             // sink：解析时触发 XXE，可读取本地文件

        var role = doc.SelectSingleNode("//assertion/role")?.InnerText ?? "";
        if (role == "admin")
        {
            context.Items["Role"] = "admin";
            await _next(context);
        }
        else
        {
            context.Response.StatusCode = 403;
            await context.Response.WriteAsync("denied: role=" + role); // 回显解析结果，可外带实体内容
        }
    }
}
