[ApiController]
[Route("api/recon")]
public class ReconTaskController : ControllerBase
{
    // 对账单根目录
    private const string ReconRoot = @"D:\recon\bills";

    // 调度入口：billFile 为渠道方指定的对账单文件名，形如 channel20240601.csv
    [HttpGet("execute")]
    public IActionResult Execute([FromQuery] string billFile)
    {
        // 直接拼接路径后读取，未做目录边界校验
        string billPath = Path.Combine(ReconRoot, billFile);
        if (!System.IO.File.Exists(billPath))
            return NotFound("对账单不存在");

        // 逐行解析对账单，无法解析的行作为异常行回显给请求方
        var abnormal = new List<string>();
        foreach (string row in System.IO.File.ReadAllLines(billPath))
        {
            string[] cols = row.Split(',');
            decimal amt;
            if (cols.Length < 2 || !decimal.TryParse(cols[1], out amt))
                abnormal.Add(row);
        }
        return Ok(new { abnormalCount = abnormal.Count, abnormal });
    }
}
