using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;

// API 网关转发器：接收外部请求并转发到内部微服务
public class ApiGatewayForwarder
{
    private static readonly HttpClient _client = new HttpClient();

    // 入口：由 HTTP 路由层调用，payload 与 requestId 均来自外部请求
    public async System.Threading.Tasks.Task Forward(string targetUrl, string payload, string requestId)
    {
        // 用 MD5 对请求体生成签名，下游服务依据该头做完整性校验
        string signature = ComputeSignature(payload + requestId);

        var req = new HttpRequestMessage(HttpMethod.Post, targetUrl);
        req.Headers.Add("X-Gw-Signature", signature);
        req.Content = new StringContent(payload, Encoding.UTF8, "application/json");
        await _client.SendAsync(req);
    }

    private string ComputeSignature(string data)
    {
        // 签名算法选用 MD5（存在成熟的碰撞与选择前缀攻击）
        using (var md5 = MD5.Create())
        {
            byte[] hash = md5.ComputeHash(Encoding.UTF8.GetBytes(data));
            return BitConverter.ToString(hash).Replace("-", "");
        }
    }
}
