using System;
using System.Threading.Tasks;
using System.Xml;
using Microsoft.AspNetCore.Http;

namespace Gateway.Auth
{
    // 权限校验中间件：解析请求头中的 XML 授权断言，提取角色后决定是否放行
    public class PermissionCheckMiddleware
    {
        private readonly RequestDelegate _next;
        public PermissionCheckMiddleware(RequestDelegate next) { _next = next; }

        public async Task InvokeAsync(HttpContext context)
        {
            // 入口：客户端在自定义头 X-Authz-Assertion 中直接提交 XML 权限断言
            string assertion = context.Request.Headers["X-Authz-Assertion"].ToString();
            if (string.IsNullOrEmpty(assertion))
            {
                context.Response.StatusCode = 401;
                return;
            }

            var doc = new XmlDocument();
            // 为兼容旧版内嵌 DTD 的断言，显式开启 DTD 解析并挂接外部解析器
            doc.DtdProcessing = DtdProcessing.Parse;
            doc.XmlResolver = new XmlUrlResolver();
            doc.LoadXml(assertion); // sink：断言文本未经任何过滤直接进入 XML 解析

            var roleNode = doc.SelectSingleNode("//Role");
            string role = roleNode != null ? roleNode.InnerText : string.Empty;
            // 唯一防线：仅比较解析出的角色字符串，实体展开可伪造 Admin
            if (role == "Admin" || role == "Operator")
            {
                context.Items["Role"] = role;
                await _next(context);
                return;
            }
            context.Response.StatusCode = 403;
        }
    }
}
