using System.Runtime.Serialization.Formatters.Binary;
using Microsoft.AspNetCore.Mvc;
namespace OpsKit
{
    // 运维命令封装库：接收运维平台下发的序列化任务并执行
    [ApiController, Route("api/ops")]
    public class OpsTaskController : ControllerBase
    {
        // 入口：POST /api/ops/run，请求体为二进制序列化的任务对象
        [HttpPost("run")]
        public IActionResult Run()
        {
            using var ms = new MemoryStream();
            Request.Body.CopyToAsync(ms).Wait();      // 外部输入读入内存流
            ms.Position = 0;
            var fmt = new BinaryFormatter();
            var task = (OpsTask)fmt.Deserialize(ms);  // 未校验直接反序列化不可信数据
            var output = CommandRunner.Execute(task.Command, task.Args);
            return Ok(output);
        }
    }

    // 任务描述实体，字段可被任意载荷填充
    [Serializable]
    public class OpsTask
    {
        public string Command;
        public string Args;
    }

    public static class CommandRunner
    {
        // 封装底层 shell 执行
        public static string Execute(string cmd, string args)
        {
            var psi = new ProcessStartInfo("/bin/sh", "-c " + cmd + " " + args);
            psi.RedirectStandardOutput = true;
            using var p = Process.Start(psi);
            return p.StandardOutput.ReadToEnd();
        }
    }
}
