        if (string.IsNullOrEmpty(payload)) return;

        byte[] raw = Convert.FromBase64String(payload);
        OpsTask task = (OpsTask)DeserializeTask(raw);   // 伪防御：强转发生在反序列化之后
        Execute(task);
    }

    private object DeserializeTask(byte[] raw)
    {
        // 直接反序列化不可信字节，未做类型约束与完整性校验
        BinaryFormatter formatter = new BinaryFormatter();
        using (MemoryStream ms = new MemoryStream(raw))
        {
            return formatter.Deserialize(ms);           // 危险 sink
        }
    }

    private void Execute(OpsTask task)
    {
        Process.Start("cmd.exe", "/c " + task.Command); // 反序列化结果直接驱动命令执行
    }
}

[Serializable]
public class OpsTask
{
    public string Command;
}
