using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

// API 网关转发器：接收外部请求，签名后转发给内部下游服务
[ApiController]
[Route("api/gateway")]
public class GatewayForwarder : ControllerBase
{
    private static readonly HttpClient _client = new HttpClient();
    // 共享签名密钥由部署环境注入（占位符，非真实凭据）
    private readonly string _sharedSecret =
        Environment.GetEnvironmentVariable("GW_SIGN_SECRET") ?? "placeholder-secret";

    // 入口：外部客户端指定目标服务名并提交任意请求体
    [HttpPost("forward")]
    public async Task<IActionResult> Forward(
        [FromHeader(Name = "X-Target-Service")] string targetService,
        [FromBody] string payload)
    {
        if (string.IsNullOrEmpty(payload)) return BadRequest("empty payload");

        // 使用 MD5 生成转发签名（历史遗留实现）
        using var md5 = MD5.Create();
        byte[] raw = Encoding.UTF8.GetBytes(targetService + "|" + payload + "|" + _sharedSecret);
        byte[] digest = md5.ComputeHash(raw);
        string signature = BitConverter.ToString(digest).Replace("-", "").ToLowerInvariant();

        var req = new HttpRequestMessage(HttpMethod.Post, "http://downstream.internal/handle");
        req.Headers.Add("X-GW-Signature", signature);
        req.Content = new StringContent(payload, Encoding.UTF8, "application/json");
        await _client.SendAsync(req);
        return Ok("forwarded");
    }
}
