    public PermissionCheckMiddleware(RequestDelegate next) { _next = next; }

    // 中间件入口：所有请求先经此权限校验
    public async Task InvokeAsync(HttpContext context)
    {
        // 客户端在自定义头中提交 XML 格式的授权策略断言
        string policyXml = context.Request.Headers["X-Auth-Policy"].ToString();
        if (string.IsNullOrEmpty(policyXml))
        {
