        // 解析 XML 策略并提取角色名用于权限判定
        XmlDocument doc = new XmlDocument();
        doc.XmlResolver = new XmlUrlResolver(); // 显式启用外部实体解析
        doc.LoadXml(policyXml);
        string role = doc.SelectSingleNode("//role").InnerText;

        if (role != "admin")
        {
            context.Response.StatusCode = 403;
            return;
        }
        await _next(context);
    }
}
