using System;
using System.Security.Cryptography;
using System.Text;

namespace ApiGateway
{
    // API 网关转发器：将客户端请求签名后转发给上游服务
    public class GatewayForwarder
    {
        // 入口：网关接收客户端转发请求，报文与时间戳均为外部输入
        public string Forward(string clientPayload, string timestamp)
        {
            // 对报文生成防篡改签名后拼入转发请求头
            string sign = BuildSignature(clientPayload + "|" + timestamp);
            return "POST /upstream HTTP/1.1\r\nX-Sign: " + sign + "\r\n\r\n" + clientPayload;
        }

        private string BuildSignature(string data)
        {
            using (var md5 = MD5.Create()) // 弱哈希：MD5 已可被碰撞攻击
            {
                byte[] hash = md5.ComputeHash(Encoding.UTF8.GetBytes(data));
                return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
            }
        }
    }
}
