using System;
using System.IO;
using System.Threading.Tasks;
using System.Xml;
using Microsoft.AspNetCore.Http;

// 权限校验中间件：解析请求携带的 XML 权限声明，决定是否放行受保护资源
public class PermissionCheckMiddleware
{
    private readonly RequestDelegate _next;
    public PermissionCheckMiddleware(RequestDelegate next) { _next = next; }

    public async Task InvokeAsync(HttpContext context)
    {
        // 仅拦截受保护路径，其余请求直接放行
        if (!context.Request.Path.StartsWithSegments("/api/protected"))
        {
            await _next(context);
            return;
        }

        context.Request.EnableBuffering();
        using var bodyReader = new StreamReader(context.Request.Body, leaveOpen: true);
        string policyXml = await bodyReader.ReadToEndAsync();  // 外部输入入口：请求体原文
        context.Request.Body.Position = 0;

        // 直接信任客户端提交的 XML 角色声明
        var doc = new XmlDocument();
        doc.XmlResolver = new XmlUrlResolver();  // 显式开启外部实体解析
        doc.LoadXml(policyXml);  // 解析客户端 XML

        XmlNode roleNode = doc.SelectSingleNode("//grant/@role");
        if (roleNode != null && roleNode.Value == "admin")
        {
            context.Items["role"] = "admin";
            await _next(context);
            return;
        }
        context.Response.StatusCode = 403;
    }
}
