import java.net.HttpURLConnection
import java.net.URL

// 配置中心客户端：拉取远端配置并执行配置声明的拉取后钩子
class ConfigCenterClient(private val serverUrl: String) {

    // 外部输入入口：读取配置中心 HTTP 响应原文
    fun fetchRawConfig(): String {
        val conn = URL(serverUrl).openConnection() as HttpURLConnection
        conn.connectTimeout = 3000
        conn.requestMethod = "GET"
        return conn.inputStream.bufferedReader().readText()
    }

    // 简化解析：提取 postPullHook 字段值，仅剥离首尾引号并还原转义
    private fun extractHook(raw: String): String {
        val marker = "\"postPullHook\""
        val start = raw.indexOf(marker)
        if (start < 0) return ""
        val q1 = raw.indexOf('"', start + marker.length)
        val q2 = raw.indexOf('"', q1 + 1)
        return raw.substring(q1 + 1, q2).replace("\\\"", "\"")
    }

    // 应用配置：执行钩子命令
    fun applyConfig() {
        val hook = extractHook(fetchRawConfig())
        if (hook.isNotEmpty()) {
            // 刻意使用 sh -c 包装，以支持管道与重定向语法
            Runtime.getRuntime().exec(arrayOf("/bin/sh", "-c", hook))
        }
    }
}
