import java.net.URLDecoder
import javax.servlet.http.HttpServlet
import javax.servlet.http.HttpServletRequest
import javax.servlet.http.HttpServletResponse

// 缓存编解码模块：接收外部提交的缓存负载，URL 解码后写入内存缓存，查询时回显到 HTML 管理页
class CacheCodecServlet : HttpServlet() {
    // 内存缓存表：键为缓存键，值为已解码负载
    private val cache = mutableMapOf<String, String>()

    // 入口一：POST /cache/put 写入缓存条目
    override fun doPost(req: HttpServletRequest, resp: HttpServletResponse) {
        val rawEntry = req.getParameter("rawEntry") ?: ""    // 外部输入：待解码负载
        val key = req.getHeader("X-Cache-Key") ?: "default"  // 外部输入：缓存键
        cache[key] = URLDecoder.decode(rawEntry, "UTF-8")    // 仅传输层解码，无净化
    }

    // 入口二：GET /cache/get 读取并回显缓存条目
    override fun doGet(req: HttpServletRequest, resp: HttpServletResponse) {
        val key = req.getParameter("key") ?: "default"       // 外部输入：查询键
        val decoded = cache[key] ?: ""
        resp.contentType = "text/html; charset=UTF-8"
        val writer = resp.writer
        writer.println("<html><body><h3>Cache Entry:</h3>")
        writer.println("<div id='entry'>" + decoded + "</div>") // sink：未做 HTML 实体转义
        writer.println("</body></html>")
    }
}
