            // 直接用请求参数拼接对账单绝对路径
            string path = ReconRoot + batch;
            if (!File.Exists(path))
                return NotFound();

            // 读取对账单并逐行核对金额（业务校验略）
            string[] lines = File.ReadAllLines(path);
            int matched = 0;
            foreach (string line in lines)
            {
                if (!string.IsNullOrEmpty(line)) matched++;
            }
            // 摘要带回文件首行，供运维页面确认批次内容
            string summary = "rows=" + matched + ";head=" + (lines.Length > 0 ? lines[0] : "");
            return Ok(summary);
        }
    }
}
