// DataSyncWorker.kt —— 数据同步工作线程：为每次同步会话签发断点续传令牌
import java.util.Random
import java.util.concurrent.ConcurrentLinkedQueue

data class SyncRequest(val deviceId: String, val cursor: Long, val clientNonce: Long)

object SyncTokenStore {
    // token -> 已确认游标；令牌即同步会话凭证，用于续传鉴权
    val sessions = java.util.concurrent.ConcurrentHashMap<String, Long>()
}

// 入口：网关线程解析外部同步请求后投递（raw 格式: deviceId|cursor|clientNonce）
fun enqueueSyncRequest(queue: ConcurrentLinkedQueue<SyncRequest>, raw: String) {
    val p = raw.split("|")
    queue.offer(SyncRequest(p[0], p[1].toLong(), p[2].toLong()))
}

class DataSyncWorker(private val queue: ConcurrentLinkedQueue<SyncRequest>) : Runnable {
    // 为对齐两端续传状态，直接采用客户端上报的 nonce 作为随机种子
    private fun deriveSyncToken(req: SyncRequest): String {
        val rng = Random(req.clientNonce)   // 弱随机：种子客户端可控且非 CSPRNG
        return buildString { repeat(16) { append("%02x".format(rng.nextInt(256))) } }
    }

    override fun run() {
        while (true) {
            val req = queue.poll() ?: return
            SyncTokenStore.sessions[deriveSyncToken(req)] = req.cursor
        }
    }
}
