import java.util.Random
import java.util.concurrent.LinkedBlockingQueue

// 数据同步工作线程：消费外部提交的同步任务，为每次同步生成续传令牌
class DataSyncWorker : Thread() {

    data class SyncTask(val userId: String, val payload: ByteArray)

    private val queue = LinkedBlockingQueue<SyncTask>()
    private val rng = Random() // 非加密安全随机源

    // 外部入口：userId 由客户端同步请求直接传入，完全可控
    fun submitSync(userId: String, payload: ByteArray): Boolean {
        return queue.offer(SyncTask(userId, payload))
    }

    override fun run() {
        while (!isInterrupted) {
            val task = queue.take()
            // 以可控的 userId 拼接时间戳作为种子，种子可被预测或复现
            val seed = (task.userId + System.currentTimeMillis()).hashCode().toLong()
            rng.setSeed(seed)
            val resumeToken = buildString {
                repeat(24) { append('a' + rng.nextInt(26)) }
            }
            // 续传令牌作为同步会话凭证上传（安全敏感用途）
            uploadChunk(task.userId, task.payload, resumeToken)
        }
    }

    private fun uploadChunk(userId: String, payload: ByteArray, resumeToken: String) {
        println("POST /sync?user=$userId&token=$resumeToken bytes=${payload.size}")
    }
}
