import java.io.Writer
import java.net.URLDecoder
import java.util.Base64

// 缓存编解码模块：负责缓存片段的编码写入与解码渲染，由 Web 框架路由调用
class CacheCodecController(private val out: Writer) {

    // 模拟缓存存储：键 -> Base64 编码后的 HTML 片段
    private val cacheStore = mutableMapOf<String, String>()

    // 入口1：PUT /cache/put，key 与 payload 均取自请求参数，用户完全可控
    fun handlePut(key: String?, payload: String?) {
        if (key.isNullOrBlank() || payload.isNullOrEmpty()) return
        // 入库前仅做 Base64 编码；编码不是净化，解码后 HTML 语义原样还原
        cacheStore[key] = Base64.getEncoder().encodeToString(payload.toByteArray())
    }

    // 入口2：GET /cache/render，rawKey 取自请求参数
    fun handleRender(rawKey: String?) {
        if (rawKey.isNullOrBlank()) return
        // URL 解码缓存键：%3Cscript%3E 会被还原成 <script>
        val key = URLDecoder.decode(rawKey, "UTF-8")
        val encoded = cacheStore[key]
        if (encoded == null) {
            // 未命中：回显解码后的键便于调试，直接拼接未转义
            out.write("<div id='cache-miss'>缓存未命中: " + key + "</div>")
            return
        }
        // 命中：Base64 解码出原始片段后拼入 HTML，未做任何 HTML 实体转义
        val html = String(Base64.getDecoder().decode(encoded))
        out.write("<div id='cache-box'>" + html + "</div>")
    }
}
