        val contentType = when {
            fileParam.endsWith(".html") -> "text/html"
            fileParam.endsWith(".png") -> "image/png"
            else -> "application/octet-stream"
        }

        // sink：按拼接路径直接读取文件字节并回传客户端
        val content = target.toFile().readBytes()
        return Pair(contentType, content)
    }
