        val ois = ObjectInputStream(ByteArrayInputStream(rawBytes))
        val doc = ois.readObject() as RichTextDocument
        ois.close()

        // 渲染进编辑器
        return renderToEditor(doc)
    }

    private fun renderToEditor(doc: RichTextDocument): String =
        "rendered:${doc.title}:${doc.htmlBody.length}"
