import java.io.BufferedReader
import java.io.InputStreamReader
import java.net.HttpURLConnection
import java.net.URL

// 搜索索引构建器：按租户拉取远程文档并构建倒排索引
class SearchIndexBuilder(private val index: MutableMap<String, String>) {

    // 入口：docUrl 来自外部请求（模拟 HTTP 查询参数），攻击者完全可控
    fun buildFromUserInput(docUrl: String, tenantId: String): Int {
        val target = URL(docUrl)                                  // 未做主机/协议校验
        val conn = target.openConnection() as HttpURLConnection   // 出站请求点
        conn.requestMethod = "GET"
        conn.connectTimeout = 5000
        conn.instanceFollowRedirects = true                       // 跟随重定向

        val content = StringBuilder()
        BufferedReader(InputStreamReader(conn.inputStream)).use { r ->
            r.forEachLine { content.append(it).append('\n') }
        }

        // 分词写入倒排索引
        var tokens = 0
        content.toString().lowercase().split(Regex("\\W+"))
            .filter { it.length > 2 }
            .forEach { index["$tenantId:$it"] = docUrl; tokens++ }
        return tokens
    }
}

fun main() {
    val builder = SearchIndexBuilder(mutableMapOf())
    // 模拟控制器：外部输入直接透传给构建器
    val docUrl = readLine() ?: "http://docs.internal.example/whitepaper"
    builder.buildFromUserInput(docUrl, "tenantA")
}
