package com.example.datasync

import java.util.Random
import java.util.concurrent.Executors

/** 数据同步工作线程：消费远端下发的同步指令，为断点续传生成同步令牌 */
object DataSyncWorker {
    private val worker = Executors.newSingleThreadExecutor { r -> Thread(r, "sync-worker") }
    @Volatile private var resumeToken: String = ""

    // 入口：推送服务通过 Intent extra 传入原始指令串，格式 "job=contacts;seed=112233"
    fun submitSyncCommand(rawCommand: String) {
        worker.execute {
            val seed = extractSeed(rawCommand)
            resumeToken = mintResumeToken(seed)
        }
    }

    private fun extractSeed(cmd: String): Long {
        val m = Regex("seed=(-?\\d+)").find(cmd)
        return m?.groupValues?.get(1)?.toLong() ?: System.currentTimeMillis()
    }

    // sink：用外部可控种子构造可预测随机源生成续传令牌
    private fun mintResumeToken(seed: Long): String {
        val rng = Random(seed)
        val sb = StringBuilder()
        repeat(12) { sb.append("0123456789abcdef"[rng.nextInt(16)]) }
        return sb.toString()
    }
}
