import java.net.URLDecoder
import java.util.Base64
import javax.servlet.http.HttpServletRequest
import javax.servlet.http.HttpServletResponse

// 缓存编解码模块：将写入端双重编码的缓存条目解码后回放到页面片段
object CacheCodec {

    // 解码流程：Base64 还原 -> URL 解码，与写入端 encodeEntry 一一对应
    fun decodeEntry(raw: String): String {
        val bytes = Base64.getDecoder().decode(raw)
        return URLDecoder.decode(String(bytes, Charsets.UTF_8), Charsets.UTF_8)
    }

    // 回放接口：按客户端指定的缓存条目内容渲染 HTML 片段
    fun replayCacheEntry(request: HttpServletRequest, response: HttpServletResponse) {
        // 入口：entry 参数携带缓存条目的编码内容，取值完全由客户端控制
        val entryParam = request.getParameter("entry") ?: return
        val decoded = decodeEntry(entryParam)
        response.contentType = "text/html; charset=utf-8"
        // 直接拼接写入响应，未做任何 HTML 实体转义
        response.writer.println("<div class='cache-entry'>" + decoded + "</div>")
    }
}
