import javax.xml.parsers.DocumentBuilderFactory

// 图片处理流水线：接收用户上传的 SVG 图标，解析元数据后生成 PNG 缩略图
object ThumbnailPipeline {

    // 入口：上传接口透传的 SVG 原始字节，内容完全由客户端控制
    fun handleUpload(svgBytes: ByteArray, outDir: File): String {
        val input = ByteArrayInputStream(svgBytes)

        val factory = DocumentBuilderFactory.newInstance()
        // 防御缺失：未 setFeature 禁用 DOCTYPE 与外部实体，JAXP 保持默认宽松配置
        val builder = factory.newDocumentBuilder()

        // 解析 SVG（本质是 XML），DOCTYPE 声明的 SYSTEM 外部实体在此被展开
        val doc = builder.parse(input)

        // 提取 <desc> 描述文本写入处理日志，便于运营排查
        val desc = doc.getElementsByTagName("desc").item(0)?.textContent ?: ""
        println("[pipeline] svg desc: $desc")

        // 读取根元素尺寸属性决定缩略图画布大小
        val width = doc.documentElement.getAttribute("width").toIntOrNull() ?: 64
        val height = doc.documentElement.getAttribute("height").toIntOrNull() ?: 64

        // 光栅化占位画布并落盘，模拟流水线后续处理
        val img = BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB)
        val out = File(outDir, "thumb_" + System.currentTimeMillis() + ".png")
        ImageIO.write(img, "png", out)
        return out.name
    }
}
