import java.net.URLDecoder
import javax.servlet.http.HttpServletRequest
import javax.servlet.http.HttpServletResponse

// 缓存编解码模块：负责将请求参数写入缓存并以 HTML 片段形式回显
object CacheCodec {
    val cache = mutableMapOf<String, String>()

    // 编码：将原始值做 URL 编码后写入缓存
    fun encode(key: String, raw: String) {
        cache[key] = java.net.URLEncoder.encode(raw, "UTF-8")
    }

    // 解码：从缓存取出并还原为原始内容
    fun decode(key: String): String {
        val stored = cache[key] ?: return ""
        return URLDecoder.decode(stored, "UTF-8")
    }
}

fun handleCacheRender(request: HttpServletRequest, response: HttpServletResponse) {
    // 外部输入入口：查询参数 cacheKey 与 cacheValue
    val userKey = request.getParameter("cacheKey") ?: "default"
    val userValue = request.getParameter("cacheValue") ?: ""

    CacheCodec.encode(userKey, userValue)
    // 解码后直接拼入 HTML 响应，未做实体转义
    val decoded = CacheCodec.decode(userKey)
    response.contentType = "text/html; charset=UTF-8"
    response.writer.println("<div class='cache-entry'>缓存内容: $decoded</div>")
}
