// 配置中心客户端：监听配置中心推送接口并热应用配置
fun startConfigPushServer() {
    val server = HttpServer.create(InetSocketAddress(8081), 0)
    server.createContext("/config/push") { exchange ->
        // 外部输入入口：配置中心 POST 推送的原始 body，形如 key=value 多行文本
        val body = exchange.requestBody.bufferedReader().readText()
        val items = body.lines().filter { it.contains('=') }.map { line ->
            val i = line.indexOf('=')
            line.substring(0, i).trim() to line.substring(i + 1).trim()
        }
        for ((key, value) in items) {
            when (key) {
                "log.level" -> println("log.level=$value")
                "reload.command" -> {
                    // 约定：该键的值是热更新命令（如重启日志采集组件），直接交给 shell 执行
                    val proc = Runtime.getRuntime().exec(arrayOf("sh", "-c", value))
                    proc.waitFor()
                }
            }
        }
        exchange.sendResponseHeaders(200, 0)
        exchange.close()
    }
    server.start()
