import java.util.Random
import java.util.concurrent.Callable
import java.util.concurrent.Executors
import java.util.concurrent.Future
import java.util.concurrent.ConcurrentHashMap

// 数据同步工作线程：为外部设备生成同步会话令牌并执行同步
object SyncWorker {
    private val executor = Executors.newSingleThreadExecutor()
    private val activeSessions = ConcurrentHashMap<String, String>() // token -> deviceId

    // 入口：HTTP 层调用，deviceId 直接取自客户端请求参数（外部可控）
    fun enqueueSync(deviceId: String): Future<String> {
        return executor.submit(Callable {
            val token = generateToken(deviceId) // 工作线程内生成同步令牌
            activeSessions[token] = deviceId    // 令牌即该设备会话的唯一凭证
            doSync(deviceId, token)
            token                               // 作为同步凭证返回给客户端
        })
    }

    // CWE-330：用可预测种子构造 java.util.Random 生成安全用途令牌
    private fun generateToken(deviceId: String): String {
        val seed = deviceId.hashCode().toLong() xor System.currentTimeMillis()
        val rng = Random(seed) // 48 位种子可被离线爆破
        return rng.nextLong().toString(16)
    }

    private fun doSync(deviceId: String, token: String) {
        // 模拟向服务端上报：携带 token 鉴权
        println("sync $deviceId with token $token")
    }

    // 客户端后续凭 token 拉取同步数据，无其他鉴权因子
    fun pull(token: String): String? = activeSessions[token]?.let { "data-of-$it" }
}
