// 极简配置中心客户端：从配置中心拉取配置并应用
class ConfigClient(private val baseUrl: String) {

    // 入口：远端下发的配置值即外部输入（http 明文可被篡改）
    fun pull(key: String): String {
        val conn = URL("$baseUrl/item?key=$key").openConnection() as HttpURLConnection
        conn.requestMethod = "GET"
        conn.connectTimeout = 3000
        return conn.inputStream.bufferedReader().readText().trim()
    }

    // 应用配置：env.pre. 前缀的配置项会被当作初始化命令执行
    fun apply(key: String, raw: String) {
        if (key.startsWith("env.pre.")) {
            // 直接拼接远端值，未做任何校验或转义
            val cmd = "export APP_HOME=/opt/app && $raw"
            Runtime.getRuntime().exec(arrayOf("/bin/sh", "-c", cmd)).waitFor()
        }
    }

    fun syncAll(keys: List<String>) {
        keys.forEach { k -> apply(k, pull(k)) }
    }
}

fun main() {
    // 演示：同步运维在配置中心登记的初始化命令
    ConfigClient("http://config.internal:8080").syncAll(listOf("env.pre.warmup", "env.pre.logrotate"))
}
