import java.io.ByteArrayInputStream
import java.io.InputStream
import javax.xml.parsers.DocumentBuilderFactory
import javax.xml.xpath.XPathConstants
import javax.xml.xpath.XPathFactory

// 图片处理流水线：接收上传的 SVG 矢量图，解析图层 id 后交给渲染器栅格化
@RestController
@RequestMapping("/pipeline/image")
class SvgLayerPipeline {

    // 入口：用户上传的 SVG 文件，字节内容完全由客户端控制
    @PostMapping("/svg/layers")
    fun extractLayers(@RequestParam("file") svgFile: MultipartFile): List<String> {
        val svgBytes = svgFile.bytes
        return parseSvgLayers(ByteArrayInputStream(svgBytes))
    }

    // SVG 本质是 XML；此处未禁用 DTD 与外部实体，默认解析器会展开 <!ENTITY> 引用
    private fun parseSvgLayers(input: InputStream): List<String> {
        val factory = DocumentBuilderFactory.newInstance()
        val builder = factory.newDocumentBuilder()
        val doc = builder.parse(input) // sink：解析阶段即展开外部实体，可读本地文件或回连内网
        val nodes = XPathFactory.newInstance().newXPath()
            .evaluate("//g/@id", doc.documentElement, XPathConstants.NODESET) as NodeList
        val out = mutableListOf<String>()
        for (i in 0 until nodes.length) out.add(nodes.item(i).nodeValue)
        return out
    }
}
