import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

// 缓存编解码模块：外部片段经 Base64 编码写入缓存，命中后解码并拼入 HTML 返回
object CacheCodec {
    private val cache = ConcurrentHashMap<String, String>()

    // 入口A：写缓存（编码侧），raw 来自外部请求参数
    fun putFragment(key: String, raw: String) {
        cache[key] = Base64.getEncoder().encodeToString(raw.toByteArray(Charsets.UTF_8))
    }

    // 入口B：读缓存（解码侧），返回值直接进入 HTTP 响应体
    fun renderFragment(key: String): String {
        val encoded = cache[key] ?: return "<div>cache-miss</div>"
        val decoded = String(Base64.getDecoder().decode(encoded), Charsets.UTF_8)
        return "<div class='fragment'>$decoded</div>" // 直接拼入响应，未做 HTML 转义
    }
}

fun handleRequest(params: Map<String, String>): String {
    // params 模拟 HTTP 查询参数，key 与 body 均为攻击者可控
    val key = params["key"] ?: "default"
    val body = params["body"] ?: ""
    if (body.isNotEmpty()) CacheCodec.putFragment(key, body)
    return CacheCodec.renderFragment(key)
}

fun main() {
    val params = mapOf("key" to "banner", "body" to "<img src=x onerror=alert(document.cookie)>")
    print(handleRequest(params))
}
