import java.sql.Connection
import java.sql.DriverManager
import com.sun.net.httpserver.HttpServer

// 用户资料查询接口：GET /api/profile?field=xxx&q=xxx
class ProfileController(private val conn: Connection) {
    fun handle(field: String, keyword: String): String {
        // 直接拼接字段名与关键字构造 SQL，未做过滤或参数化
        val sql = "SELECT id, username, email FROM user_profile WHERE $field LIKE '%$keyword%'"
        val rs = conn.createStatement().executeQuery(sql)
        val sb = StringBuilder()
        while (rs.next()) {
            sb.append(rs.getInt("id")).append(',').append(rs.getString("username")).append(',').append(rs.getString("email")).append('\n')
        }
        rs.close()
        return sb.toString()
    }
}

fun main() {
    val conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/appdb?user=app&password=" + System.getenv("DB_PWD"))
    val controller = ProfileController(conn)
    val server = HttpServer.create(InetSocketAddress(8080), 0)
    server.createContext("/api/profile") { exchange ->
        // 解析 URL 查询参数作为外部输入入口
        val query = exchange.requestURI.rawQuery ?: ""
        val params = query.split('&').associate { p ->
            val kv = p.split('=', limit = 2)
            (kv[0] to (if (kv.size > 1) URLDecoder.decode(kv[1], "UTF-8") else ""))
        }
        val field = params["field"] ?: "username"  // 外部输入1：查询字段
        val keyword = params["q"] ?: ""            // 外部输入2：查询关键字
        val body = controller.handle(field, keyword).toByteArray()
        exchange.sendResponseHeaders(200, if (body.isEmpty()) -1 else body.size.toLong())
        exchange.responseBody.use { it.write(body) }
    }
    server.start()
}
