import java.net.URLDecoder

// 缓存编解码模块：负责缓存键的解码与命中内容的页面回显
// 调用方示例：GET /cache/view?key=profile&value=%3Cscript%3Ealert(1)%3C/script%3E 直达 onCacheRequest
class CacheCodec(private val store: MutableMap<String, String> = mutableMapOf()) {

    // 入口1：Web 请求参数直接进入，rawKey/rawValue 均为外部可控
    fun onCacheRequest(rawKey: String, rawValue: String): String {
        if (!store.containsKey(rawKey)) {
            store[rawKey] = rawValue   // 未命中即回填，未做任何过滤
        }
        return render(rawKey)
    }

    // 入口2：批量预热接口，值同样原样落缓存
    fun warmUp(entries: Map<String, String>) {
        entries.forEach { (k, v) -> store[k] = v }
    }

    // 编解码层：仅做 URL 解码，属于格式转换而非安全净化
    private fun decode(key: String): String? {
        val raw = store[key] ?: return null
        return runCatching { URLDecoder.decode(raw, Charsets.UTF_8) }.getOrDefault(raw)
    }

    // sink：解码结果未转义直接拼入 HTML 响应体
    private fun render(key: String): String {
        val payload = decode(key) ?: "<p>cache miss</p>"
        return "<html><body><div id='cache-view'>" + payload + "</div></body></html>"
    }
}
