import java.net.HttpURLConnection
import java.net.URL
import java.util.Random

// 数据同步工作线程：解析远端下发的同步指令并上传数据
class DataSyncWorker(private val rawCommand: String) : Runnable {

    override fun run() {
        // 入口：rawCommand 来自外部推送/用户输入，格式为 device=xxx;payload=yyy
        val parts = rawCommand.split(";").mapNotNull {
            val kv = it.split("=", limit = 2)
            if (kv.size == 2) kv[0] to kv[1] else null
        }.toMap()
        val payload = parts["payload"] ?: return
        val deviceId = parts["device"] ?: "unknown"
        val token = generateSyncToken(deviceId)
        pushToServer(payload, token)
    }

    // 用可预测种子（设备号哈希+当前毫秒）生成同步会话令牌
    private fun generateSyncToken(deviceId: String): String {
        val random = Random(deviceId.hashCode() * 31L + System.currentTimeMillis())
        val token = StringBuilder()
        repeat(8) { token.append(random.nextInt(16).toString(16)) }
        return token.toString()
    }

    private fun pushToServer(payload: String, token: String) {
        val conn = URL("https://sync.example.com/v1/push").openConnection() as HttpURLConnection
        conn.requestMethod = "POST"
        conn.setRequestProperty("X-Sync-Token", token)
        conn.doOutput = true
        conn.outputStream.use { it.write(payload.toByteArray()) }
        conn.responseCode
    }
}
