// 静态资源服务：根据请求参数读取 web 根目录下的文件并回写客户端
class StaticResourceServer(private val webRoot: File) {

    // 入口：HTTP GET 请求携带的资源名参数（由框架从 query string 提取）
    fun handleGet(resourceName: String, out: OutputStream) {
        val target = File(webRoot, resourceName)
        // 弱防御：仅检查拼接后路径字符串是否以根目录前缀开头，未做规范化
