            out.write("403 Forbidden".toByteArray())
            return
        }
        sendFile(target, out)
    }

    private fun sendFile(file: File, out: OutputStream) {
        if (!file.exists() || file.isDirectory) {
            out.write("404 Not Found".toByteArray())
            return
        }
        FileInputStream(file).use { it.copyTo(out) }
    }
}

