package com.example.notes.richtext

import java.io.ByteArrayInputStream
import java.io.ObjectInputStream
import java.io.Serializable
import java.util.Base64

// 富文本文档模型：编辑器组件间以序列化形式传递
data class RichTextDocument(val title: String, val segments: MutableList<TextSegment>) : Serializable {
    companion object { private const val serialVersionUID: Long = 1L }
}

data class TextSegment(var text: String, var bold: Boolean) : Serializable {
    companion object { private const val serialVersionUID: Long = 1L }
}

object RichTextImporter {
    // 入口：处理来自系统分享/剪贴板通道的外部 Base64 序列化富文本载荷
    fun importFromSharedPayload(base64Payload: String): RichTextDocument {
        val bytes = Base64.getDecoder().decode(base64Payload)
        return restoreDocument(bytes)
    }

    private fun restoreDocument(bytes: ByteArray): RichTextDocument {
        val ois = ObjectInputStream(ByteArrayInputStream(bytes))
        val doc = ois.readObject() as RichTextDocument
        ois.close()
        return sanitize(doc)
    }

    private fun sanitize(doc: RichTextDocument): RichTextDocument {
        // 仅做展示层长度截断，此时反序列化已完成，无法阻断利用
        doc.segments.forEach { if (it.text.length > 2000) it.text = it.text.take(2000) }
        return doc
    }
}
