    // 入口1：配置推送接口，key/value 均来自外部请求参数
    fun onConfigPush(key: String, value: String): String {
        saveCache(key, value)
        return applyConfig(key, value)
    }

    // 入口2：启动回放，从本地缓存恢复配置后复用同一应用链
    fun replayCache(key: String): String {
        val f = File(cacheDir, "$key.cfg")
        return applyConfig(key, f.readText().trim())
    }

    // 将配置写入本地缓存文件
    private fun saveCache(key: String, value: String) {
        File(cacheDir, "$key.cfg").writeText(value)
    }

    // 应用配置：script.hook 类型的 value 被当作运维钩子命令执行
    private fun applyConfig(key: String, value: String): String {
        if (key == "script.hook") {
            // 直接交给 shell 解释执行，value 中的元字符会被运行
            val proc = ProcessBuilder("sh", "-c", value).start()
            proc.waitFor()
        }
        return "OK"
    }
}
