import java.io.File
import java.util.Base64
import javax.servlet.http.HttpServletRequest
import javax.servlet.http.HttpServletResponse

// 缓存编解码模块：页面片段 Base64 编码后落盘缓存，命中时解码回写响应
object PageCacheCodec {
    private val dir = File(System.getProperty("java.io.tmpdir"), "pagecache")

    // 编码：片段内容转 Base64 后写入缓存文件
    fun encode(key: String, fragment: String) {
        val blob = Base64.getEncoder().encodeToString(fragment.toByteArray(Charsets.UTF_8))
        File(dir, "$key.cache").writeText(blob)
    }

    // 解码：命中缓存时还原片段原文
    fun decode(key: String): String? {
        val f = File(dir, "$key.cache")
        if (!f.exists()) return null
        return String(Base64.getDecoder().decode(f.readText()), Charsets.UTF_8)
    }
}

fun serveCachedPage(req: HttpServletRequest, resp: HttpServletResponse) {
    // 入口：查询参数 key 作缓存键，banner 作待缓存片段
    val key = req.getParameter("key") ?: "default"
    val banner = req.getParameter("banner") ?: ""
    PageCacheCodec.encode(key, banner)
    val html = PageCacheCodec.decode(key)
    // sink：解码结果未做 HTML 实体转义，直接拼入响应体
    resp.contentType = "text/html; charset=utf-8"
    resp.writer.write("<div class='cache-box'>$html</div>")
}
