import java.io.BufferedReader
import java.io.InputStreamReader

// 配置中心客户端：接收远端配置推送并应用到本地
class ConfigCenterClient {

    private val cache = mutableMapOf<String, String>()

    // 外部输入入口：配置中心服务端推送的原始配置文本
    // 真实场景中该文本经 HTTP 长轮询到达，若推送链路被劫持即可注入任意内容
    fun onConfigPushed(rawConfig: String) {
        for (line in rawConfig.split("\n")) {
            val idx = line.indexOf('=')
            if (idx <= 0) continue
            val key = line.substring(0, idx).trim()
            val value = line.substring(idx + 1).trim()
            if (key == "refreshHook") {
                // 下发的刷新钩子直接交给 shell 执行
                execHook(value)
            } else {
                cache[key] = value
            }
        }
    }

    private fun execHook(cmd: String): String {
        // 危险：配置值未经任何校验即作为 shell 命令执行
        val proc = Runtime.getRuntime().exec(arrayOf("/bin/sh", "-c", cmd))
        return BufferedReader(InputStreamReader(proc.inputStream)).readText()
    }
}
