    // 入口：HTTP 接口 /index/rebuild 的查询参数 sourceUrl 直接传入本方法
    fun rebuildIndex(sourceUrl: String, tenant: String): String {
        // 弱校验：仅拦截 http://localhost 前缀，未覆盖内网 IP 与重定向
        if (!sourceUrl.startsWith("http://")) {
            throw IllegalArgumentException("only http supported")
        }
        if (sourceUrl.startsWith("http://localhost")) {
            throw IllegalArgumentException("blocked host")
        }

        // 用户可控 URL 直接发起服务端请求
        val conn = URL(sourceUrl).openConnection() as HttpURLConnection
        conn.connectTimeout = 3000
        conn.instanceFollowRedirects = true

        // 响应体写入索引，可被搜索接口读回
        val body = conn.inputStream.bufferedReader().use { it.readText() }
        conn.disconnect()

        indexStore["tenant:$tenant"] = body
        return "indexed ${body.length} chars"
    }
}
