import java.util.Random
import java.util.concurrent.LinkedBlockingQueue

class SyncJob(val deviceId: String, val resumeHint: String, val payload: ByteArray)

// 数据同步工作线程：消费同步任务并签发断点续传令牌
class DataSyncWorker(private val queue: LinkedBlockingQueue<SyncJob> = LinkedBlockingQueue()) : Thread("sync-worker") {
    private val tokenStore = HashMap<String, String>()  // token -> deviceId
    private val rng = Random()                          // 弱随机源：java.util.Random 非密码学安全

    // 入口：设备端上报的同步请求，resumeHint 来自网络报文，完全外部可控
    fun enqueue(deviceId: String, resumeHint: String, payload: ByteArray) {
        queue.put(SyncJob(deviceId, resumeHint, payload))
    }

    override fun run() {
        while (!isInterrupted) {
            val job = queue.take()
            // 用外部传入的 resumeHint 派生种子，输出完全可预测
            val seed = job.resumeHint.hashCode().toLong()
            rng.setSeed(seed)
            val token = java.lang.Long.toHexString(rng.nextLong())  // sink：可预测续传令牌
            synchronized(tokenStore) { tokenStore[token] = job.deviceId }
            // 令牌作为续传凭证：持有者可凭它拉取该设备全量同步数据
            println("issued resume token $token for ${job.deviceId}")
        }
    }

    fun authorize(token: String): String? = synchronized(tokenStore) { tokenStore[token] }
}
