    fun encode(key: String, html: String): String = "k=$key;v=$html"
    fun decode(raw: String): String = raw.substringAfter("v=", missingDelimiterValue = "")
}

// 简易缓存存储，模拟可能为空的分布式缓存
object CacheStore {
    private val store = mutableMapOf<String, String>()
    fun get(key: String): String? = store[key]
    fun put(key: String, value: String) { store[key] = value }
}

fun handleCacheLookup(request: HttpServletRequest, response: HttpServletResponse) {
    // 入口1：cacheKey 指定缓存条目，未命中时回源构造片段
    val cacheKey = request.getParameter("cacheKey") ?: return
    val cached = CacheStore.get(cacheKey)
        ?: CacheEntryCodec.encode(cacheKey, "<div>片段 $cacheKey</div>")
    // 入口2：render 参数允许调用方追加自定义页脚
    val footer = request.getParameter("render") ?: ""
    val fragment = CacheEntryCodec.decode(cached) + footer
    // sink：解码结果未做 HTML 实体转义，直接写入响应体
    response.contentType = "text/html; charset=utf-8"
    response.writer.print(fragment)
