import java.util.Random
import java.util.concurrent.LinkedBlockingQueue

// 数据同步工作线程：从共享队列取外部提交的任务，生成本次同步会话令牌并上报
data class SyncTask(val deviceId: String, val payload: String)

object SyncTokenIssuer {
    // 缺陷：安全用途却使用可预测的 java.util.Random，种子仅为当前毫秒时间戳
    private val rng = Random(System.currentTimeMillis())

    fun issueToken(deviceId: String): String {
        val n = rng.nextLong()
        return deviceId + "-" + java.lang.Long.toHexString(n)
    }
}

class SyncWorker(private val queue: LinkedBlockingQueue<SyncTask>) : Thread("sync-worker") {
    override fun run() {
        while (!isInterrupted) {
            val task = queue.take()                   // 外部输入入口：任意线程可投递任务
            if (task.payload.length > 4096) continue  // 仅长度限制，与随机性无关
            val token = SyncTokenIssuer.issueToken(task.deviceId)
            sendSync(task.deviceId, token, task.payload)
        }
    }

    private fun sendSync(deviceId: String, token: String, payload: String) {
        // token 作为同步会话凭据随请求发送
        println("POST /sync dev=$deviceId token=$token bytes=${payload.length}")
    }
}
