        get("/static") {
            // 入口：查询参数 file 完全由客户端控制
            val name = call.request.queryParameters["file"] ?: return@get
            // 文档根目录固定，但拼接时未过滤 ../ 等穿越序列
            val docRoot = File("/var/www/docs")
            val target = File(docRoot, name)
            // 仅判断存在性，未校验解析后路径是否仍位于 docRoot 内
            if (target.exists() && target.isFile) {
                // sink：读取文件字节并原样回显给客户端
                call.respondBytes(target.readBytes())
            } else {
                call.respondText("not found")
            }
        }
    }
}
