代码片段（语言: kotlin）：
```kotlin
import java.io.File
import java.net.HttpURLConnection
import java.net.URL

// 配置中心客户端：拉取远端配置并执行发布后钩子
class ConfigCenterClient(private val serverUrl: String) {

    // 入口：拉取配置中心响应，响应体即外部可控输入
    fun pull(namespace: String): Map<String, String> {
        val conn = URL("$serverUrl/configs/$namespace").openConnection() as HttpURLConnection
        val body = conn.inputStream.bufferedReader().readText()
        return body.lineSequence()
            .filter { it.contains('=') }
            .map { val p = it.split('=', limit = 2); p[0].trim() to p[1].trim() }
            .toMap()
    }

    // 应用配置：约定 hook.command 为发布后清理脚本
    fun apply(config: Map<String, String>) {
        val hook = config["hook.command"] ?: return
        val dir = File(config["hook.dir"] ?: "/tmp")
        // 直接交给 shell 解释执行，未做任何过滤或校验
        val proc = Runtime.getRuntime().exec(arrayOf("/bin/sh", "-c", hook), null, dir)
        proc.waitFor()
    }
}

fun main() {
    val client = ConfigCenterClient("http://config-center.internal:8080")
    client.apply(client.pull("app-prod"))
}
